packages.behavior:
// Roller Conveyor — a powered roller bed. Demonstrates a conveying deck link: the behavior sets the surface
// velocity along the flow axis (+X) and the host carries any cargo on the bed. A negative speed reverses it;
// a PLC run tag can start/stop it. The rollers are decorative (the deck is the surface).

let odo = 0 // encoder odometer: belt surface travel (m)

definePart({
  params: {
    // 'face' handles add viewport resize dots: a ±X dot drives length, ±Z drives width (clamped to the
    // param's min/max); the host reflows the rig live. length has no max — a roller bed can be any length.
    length: { type: 'number', default: 4, min: 0.5, step: 0.1, label: 'Length (m)', handle: { kind: 'face', axis: 'x' }, desc: 'Bed length along travel. Drag the dot on either end face to resize in the viewport; there is no upper limit, so one bed can stand in for a long run.' },
    width: { type: 'number', default: 1.524, min: 0.2, max: 3, step: 0.05, label: 'Width (m)', handle: { kind: 'face', axis: 'z' }, desc: 'Bed width across travel. Drag the dot on either side face to resize in the viewport.' },
    speed: { type: 'number', default: 1.0, min: -3, max: 3, step: 0.1, label: 'Speed (m/s, − reverses)', desc: 'Surface speed carried along the bed. Negative runs the rollers backwards, which is the ONLY way to reverse flow - rotating the part 180 degrees moves its ends instead. A program can command this through the speed tag below.' },
    // skew — angle the rollers for angled product movement: cargo tracks across the bed and squares against
    // a side guard. rollerLayout() rotates the rollers (lengthened to width/cos, clipped to the frame
    // corners) and step() angles the surface velocity to match; the guard collision does the squaring.
    skew: { type: 'number', default: 0, min: -60, max: 60, step: 1, label: 'Roller skew (deg)', desc: 'Angle the rollers so cargo drifts sideways as it travels and squares itself against a side guard - the standard way to align product before a merge or a labeller. The surface velocity follows the angle, and the guard does the squaring, so leave the guard on that side up.' },
    // incline — tilt the whole rigid bed about its centre, +X head up. Host-owned via the rig inclineParam
    // marker: geometry + collision tilt as one, the trestle legs regrow to the floor, and the deck's surface
    // velocity gets the tilted tangent — so step() needs no incline math. ±30°: rollers shed product on a
    // steeper grade, unlike belts which hold it.
    tiltDeg: { type: 'number', default: 0, min: -30, max: 30, step: 1, label: 'Incline (deg, + = head up)', desc: 'Tilt the whole bed about its centre, positive lifting the head. This is the way to incline a roller bed - do NOT rotate the part itself, which would tip its snap ends too. Legs regrow to the floor automatically. Kept to 30 degrees because rollers shed product on a steeper grade, where a belt would hold it.' },
    // guard toggles — a false showParam removes the wall's render AND its collision body (a real opening,
    // not just hidden), so cargo can be diverted off / loaded on. Left = −Z, right = +Z (belt convention).
    leftGuard: { type: 'boolean', default: true, label: 'Left side guard', group: 'Side Guards', desc: 'Guard wall down the left side, looking along travel. This is a real barrier, so turning it off lets cargo leave the bed sideways.' },
    rightGuard: { type: 'boolean', default: true, label: 'Right side guard', group: 'Side Guards', desc: 'Guard wall down the right side, looking along travel. This is a real barrier, so turning it off lets cargo leave the bed sideways.' },
    // side-guard openings as [start m, end m, side] rows — measured from the TAIL (upstream end), side −1 =
    // left, +1 = right, 0 = both. Same rows, same meaning as the belt conveyor's; press G with the bed
    // selected to drag them in the viewport. Cuts a gap in the guard wall's render AND collision (a sensor,
    // a hand transfer). The rig guard links are what get split, so the host consumes this param rather than
    // geometry() — declaring it is the opt-in (core/guardOpenings.ts addAuthoredOpenings).
    // Neighbour-auto openings (a guard opening itself where another conveyor butts) stay a host concern.
    guardOpenings: { type: 'numberList', arity: 3, default: [], label: 'Guard openings [start m, end m, side ±1/0]', group: 'Side Guards', desc: 'Gaps cut in the guard wall, measured as distance ALONG the bed from the tail. Side -1 is left, +1 is right, 0 cuts both. Each gap opens the collision as well as the mesh, which is how a transfer or a diverter gets product off the lane. Press G with the bed selected to drag them in the viewport.' },
    // deck height above the floor — drives the leg length. rest:'surfaceBelow' lets the host auto-fill it
    // from the surface beneath at drop/snap, so the legs auto-adjust to reach the floor (or a platform).
    standHeight: { type: 'number', default: 2.0, min: 0.1, max: 3, step: 0.01, rest: 'surfaceBelow', label: 'Stand height (m)', desc: 'Height of the deck above whatever is beneath it, which sets the leg length. The host fills this in when you drop or snap the conveyor, so the legs reach the floor - or a platform crossing underneath - without you measuring. Pin it by hand when you want a deliberate height.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', desc: 'Expose this conveyor to the PLC. The tags below do nothing until this is on.' },
    // Comms trio: speedTag = REAL setpoint in (replaces the speed param), runningTag = BOOL feedback out
    // (effective speed ≠ 0); runTag = BOOL run/stop gate (back-compat).
    speedTag: { type: 'tag', dir: 'in', stType: 'REAL', setpointFor: 'speed', default: '', label: 'Speed tag (REAL in: commanded speed, m/s)', desc: 'The program commands surface speed here, replacing the Speed field above, which then shows the live value read-only. Careful: once BOUND this takes over even if no program drives it, and an undriven tag reads 0 - so a half-wired conveyor sits still rather than running at its authored speed.' },
    runTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Run tag (rollers run while true)', desc: 'Start/stop gate: false forces the speed to 0 whatever the setpoint says. Unlike the speed tag, this only takes effect once a program actually DRIVES it, so binding it alone will not stop the bed.' },
    runningTag: { type: 'tag', dir: 'out', stType: 'BOOL', default: '', label: 'Running tag (BOOL out: speed ≠ 0)', desc: 'Feedback the conveyor publishes for the program to read: true whenever it is actually moving. This is the EFFECTIVE speed, gates included, so a run tag holding it at zero reads false here.' },
    // encoder feedback (REAL out): the odometer of belt surface travel in metres, integrated on sim time —
    // track product by distance off this (latch at a photo-eye, act at an offset).
    encoderTag: { type: 'tag', dir: 'out', stType: 'REAL', default: '', label: 'Encoder tag (REAL out: belt travel, m)', desc: 'Odometer of surface travel in metres, integrated on sim time and only ever climbing. Latch it when a photo-eye sees a box, then act once it has advanced a known distance - the standard way to track product without a sensor at every station.' },
  },
  // Geometry — the skew transfer plates: the light-steel corner dead-plates that fill the triangular gaps
  // the angled rollers leave at the head/tail once skewed. Render-only, emitted on the 'roller' rig link so
  // they ride the incline.
  //
  // `ctx` is the host-resolved seam (GeometryContext): the world-phase roller grid this bed landed on, plus
  // which of its ends abut a collinear neighbour. The plate needs it because it REPLACES the rollers the skew
  // clipped away, so at a butt it has to finish where a roller would have. Ending it flush at the bed end
  // leaves up to (pitch - R) of bare deck at the transfer — the neighbour's first roller is on the shared
  // grid, wherever the pair happens to sit in world X — against the ONE roller gap an unskewed bed shows
  // there. See the lip below.
  geometry(g, p, ctx) {
    var skewRad = (typeof p.skew === 'number' ? p.skew : 0) * Math.PI / 180
    if (Math.abs(skewRad) < 1e-4) return []
    var width = typeof p.width === 'number' ? p.width : 1.524
    var length = typeof p.length === 'number' ? p.length : 4
    if (width <= 0 || length <= 0) return []
    var R = 0.024 // matches the rig roller radius
    // the 'roller' link group sits R below the deck; lift the plate top to roller-top level + a hair (no z-fight),
    // dropping a 2R skirt so it reads as a solid plate, not a paper-thin sheet.
    var yTop = R + 0.001, yBot = yTop - 2 * R
    var halfW = width / 2, headX = length / 2, tailX = -length / 2
    // X-extent of the triangular gap the angled rollers leave at each end (clamped to the length)
    var skewZone = Math.min(halfW * Math.abs(Math.tan(skewRad)), length)
    var headInset = headX - skewZone, tailInset = tailX + skewZone
    var zSign = skewRad > 0 ? 1 : skewRad < 0 ? -1 : 1 // which diagonal each plate leans along (the union is the same either way)
    var s = g.surface()
    function tri(ax, ay, az, bx, by, bz, cx, cy, cz) { s.triangle(s.vertex(ax, ay, az), s.vertex(bx, by, bz), s.vertex(cx, cy, cz)) }
    // one triangular dead-plate: top face v1-v3-v2 + a skirt down the v1-v3 (diagonal) and v2-v3 (end) edges (the
    // v1-v2 edge sits against the frame wall, no skirt). doubleSided, so winding is cosmetic.
    function plate(x1, z1, x2, z2, x3, z3) {
      tri(x1, yTop, z1, x3, yTop, z3, x2, yTop, z2)
      tri(x1, yTop, z1, x1, yBot, z1, x3, yBot, z3); tri(x3, yBot, z3, x3, yTop, z3, x1, yTop, z1)
      tri(x2, yTop, z2, x2, yBot, z2, x3, yBot, z3); tri(x3, yBot, z3, x3, yTop, z3, x2, yTop, z2)
    }
    plate(headInset, zSign * halfW, headX, zSign * halfW, headX, 0)
    plate(headInset, -zSign * halfW, headX, -zSign * halfW, headX, 0)
    plate(tailInset, -zSign * halfW, tailX, -zSign * halfW, tailX, 0)
    plate(tailInset, zSign * halfW, tailX, zSign * halfW, tailX, 0)
    // TRANSFER LIP — the full-width strip that carries the plate across a butt seam to the neighbour's first
    // roller. Two beds butted end to end share ONE world pitch grid, so that roller sits on the next grid line
    // past this end: lap out to its face (grid line -/+ R) and the transfer is continuous at every phase.
    // Bounded by R, the most a roller of our own would ever poke past the frame, which is also what stops the
    // lip from cutting THROUGH the neighbour's roller when that roller lands right at the seam. Gated on
    // `butt`: at a free end there is nothing to meet, so the plate stays flush with the frame as before.
    // Both fall back to 0 without a ctx (headless / parity call) — the placement-free plate.
    var c = ctx || {}
    var deltas = c.deltas, pitch = typeof c.pitch === 'number' ? c.pitch : 0
    var butt = c.butt || { head: false, tail: false }
    var gridded = !!deltas && deltas.length > 0 && pitch > 0
    // bare deck between our end and the neighbour's first roller face, clamped to [0, R]
    function lapTo(on, edge, line) {
      if (!on || !gridded) return 0
      return Math.max(0, Math.min(R, Math.abs(line - edge) - R))
    }
    var lapHead = lapTo(butt.head, headX, gridded ? deltas[deltas.length - 1][0] + pitch : 0)
    var lapTail = lapTo(butt.tail, tailX, gridded ? deltas[0][0] - pitch : 0)
    // one end lip: the top strip from the bed end out to x2, plus the same 2R skirt the plates carry on its
    // outer edge so it still reads as steel rather than a paper sheet. doubleSided, so winding is cosmetic.
    function lip(x1, x2) {
      if (Math.abs(x2 - x1) < 1e-5) return
      tri(x1, yTop, -halfW, x2, yTop, -halfW, x2, yTop, halfW)
      tri(x1, yTop, -halfW, x2, yTop, halfW, x1, yTop, halfW)
      tri(x2, yTop, -halfW, x2, yBot, -halfW, x2, yBot, halfW)
      tri(x2, yBot, halfW, x2, yTop, halfW, x2, yTop, -halfW)
    }
    lip(headX, headX + lapHead)
    lip(tailX, tailX - lapTail)
    return [{ desc: s.build(), role: 'gapfill', link: 'roller', castShadow: false, doubleSided: true }]
  },
  // Roller layout — shape each roller from the host-resolved, world-phased grid `deltas`. Straight:
  // full-length rollers (yaw 0) at every grid line. Skewed: rotate each about +Y by `skew`, lengthen to
  // axle/cos so it spans the bed, and clip to the frame corners. The rig `stub` follows each roller.
  rollerLayout(deltas, p) {
    var skewRad = (typeof p.skew === 'number' ? p.skew : 0) * Math.PI / 180
    var width = typeof p.width === 'number' ? p.width : 1.524
    var length = typeof p.length === 'number' ? p.length : 4
    var axle = width - 0.004 // matches the roller shape sizeParams (axis 0: width, add -0.004)
    var out = []
    var sin = Math.sin(skewRad)
    if (Math.abs(sin) < 1e-6) {
      for (var i = 0; i < deltas.length; i++) out.push({ x: deltas[i][0], z: 0, yaw: 0, length: axle })
      return out
    }
    // skewed: the rotated shaft is parameterised by t ∈ [-full/2, full/2]; clip t to BOTH the shaft extent and the
    // frame ends X = ±halfLen (X = dx + t·sin). The visible segment's length + centre offset give the roller.
    var R = 0.024 // rendered roller radius
    var cos = Math.cos(skewRad)
    var full = axle / Math.abs(cos) // width/cos — spans wall-to-wall when rotated
    var halfShaft = full / 2
    var halfLen = length / 2 - R * Math.abs(cos) // effective half-length (inset a roller radius)
    for (var k = 0; k < deltas.length; k++) {
      var dx = deltas[k][0]
      var tPos = (halfLen - dx) / sin, tNeg = (-halfLen - dx) / sin
      var tMin, tMax
      if (sin > 0) { tMax = Math.min(halfShaft, tPos); tMin = Math.max(-halfShaft, tNeg) }
      else { tMax = Math.min(halfShaft, tNeg); tMin = Math.max(-halfShaft, tPos) }
      var clipLen = tMax - tMin
      if (clipLen <= 0.02) continue // a sliver at the very corner — drop it
      var offset = (tMax + tMin) / 2
      out.push({ x: dx + offset * sin, z: offset * cos, yaw: skewRad, length: clipLen })
    }
    return out
  },
  step(ctx) {
    // Comms precedence: speedTag (REAL in) replaces the speed param as the commanded speed; runTag (BOOL)
    // gates it to 0, but ONLY while a controller actually drives the tag (ctx.tagDriven, output ownership) —
    // undriven, the authored speed rules; runningTag (BOOL out) = effective speed ≠ 0, written every step.
    const comms = ctx.params.enableComms
    const commanded = comms && ctx.params.speedTag ? ctx.readNumber(ctx.params.speedTag) : ctx.params.speed
    const running = comms && ctx.tagDriven(ctx.params.runTag) ? ctx.readTag(ctx.params.runTag) : true
    const s = running ? commanded : 0
    // the readout the Inspector shows for 'speed' while a setpoint tag owns it: the EFFECTIVE value,
    // gates and all, not the raw setpoint (a runTag holding this at 0 must not read as the commanded rate)
    ctx.report('speed', s)
    if (comms && ctx.params.runningTag) ctx.writeTag(ctx.params.runningTag, s !== 0)
    odo += s * ctx.dt
    if (comms && ctx.params.encoderTag) ctx.writeNumber(ctx.params.encoderTag, odo)
    // skew: the rollers are angled about vertical, so drive along the roller normal — forward rotated by
    // skew (right-handed about +Y) at magnitude s/cos(skew), so the forward throughput stays s and the
    // lateral s·tan(skew) squares cargo against the guard.
    const skewRad = (ctx.params.skew || 0) * Math.PI / 180
    const c = Math.cos(skewRad), sn = Math.sin(skewRad)
    const mag = Math.abs(c) > 1e-3 ? s / c : s
    const fx = ctx.forward.x, fz = ctx.forward.z
    ctx.setSurfaceVelocity({ x: (fx * c + fz * sn) * mag, y: 0, z: (-fx * sn + fz * c) * mag })
  },
})

// Box Spawner — a hopper that emits cargo boxes. Demonstrates ctx.spawn: the behavior runs its own rate
// timer and emits a box every 60/boxesPerMinute seconds; the host creates the dynamic cargo body at the
// part's pose + the given local offset. Cargo drops at the exact spawn point (no positional scatter), so
// downstream handling (picks, aligned queues) sees a repeatable pose. Optionally gated by a conveyor
// interlock (conveyorId → ctx.conveyorRunning) or a PLC run tag.
//
// A hopper is PACED, not commanded: what the author sets is the INTERVAL BETWEEN boxes, so that is what a hold
// preserves. The countdown therefore keeps running while the gate is shut but floors at zero — a hold neither
// costs a period nor banks one. Freeze it instead and every release pays out the remainder of an interval the
// hopper spent standing still (in the PLC demo: ~2.7 s of empty lane at the top of every row); let it run
// unfloored and a long hold banks a burst that all lands in one tick.
// This is the opposite rule from the pallet spawner, deliberately: a MAGAZINE is commanded, so it re-arms on
// every enable and drops at once, which is what makes a sub-period command pulse dispense exactly one.

// random-size range, full box dimensions (m)
const SIZE_MIN = [0.4, 0.3, 0.3]
const SIZE_MAX = [0.8, 0.5, 0.5]

let countdown = 0 // seconds until the next spawn
let started = false // arm the first box on the first eligible tick
let colorIndex = 0

// parse "#rrggbb" → [r, g, b] in 0..1
function hexRgb(hex) {
  const h = (hex || '').replace('#', '')
  if (h.length < 6) return [1, 1, 1]
  const v = (i) => { const n = parseInt(h.slice(i, i + 2), 16); return Number.isFinite(n) ? n / 255 : 1 }
  return [v(0), v(2), v(4)]
}
// parse a comma-separated hex list → [[r,g,b], …]
function palette(csv) {
  return (csv || '').split(',').map((c) => c.trim()).filter((c) => c.length >= 6).map(hexRgb)
}

definePart({
  params: {
    boxesPerMinute: { type: 'number', default: 45, min: 0, max: 1000, step: 1, label: 'Boxes per minute', desc: 'Feed rate. 0 halts the feed without disabling the part, so the timer restarts cleanly when you raise it again.' },
    fixedRate: { type: 'boolean', default: true, label: 'Fixed rate (off = ±50% jitter)', desc: 'On, boxes arrive on an exact metronome. Off, each gap is randomised between half and one-and-a-half times the nominal period, which is what an untidy real feed looks like downstream.' },
    boxColor: { type: 'color', default: '#cc8844', label: 'Box colour', group: 'Box', desc: 'Tint for every spawned box. Ignored once the cycle list below is non-empty.' },
    boxColors: { type: 'string', default: '', label: 'Box colours (cycle, comma-sep hex)', group: 'Box', desc: 'Comma-separated hex list handed out one per box, overriding the single colour above. Useful for telling sorted lanes apart at a glance. Leave empty to use the single colour.' },
    randomColors: { type: 'boolean', default: false, label: 'Random colour order', group: 'Box', desc: 'Draw each colour at random from the cycle list instead of walking the list in order.' },
    length: { type: 'number', default: 0.6, min: 0.1, max: 2, step: 0.05, label: 'Box length (m)', group: 'Box', desc: 'Extent along local X of each spawned box. Ignored while Random size is on.' },
    width: { type: 'number', default: 0.4, min: 0.1, max: 2, step: 0.05, label: 'Box width (m)', group: 'Box', desc: 'Extent along local Z of each spawned box. Ignored while Random size is on.' },
    height: { type: 'number', default: 0.4, min: 0.1, max: 2, step: 0.05, label: 'Box height (m)', group: 'Box', desc: 'Extent along local Y of each spawned box. Ignored while Random size is on.' },
    randomSize: { type: 'boolean', default: false, label: 'Random size', group: 'Box', desc: 'Give each box a random size and IGNORE the three dimensions above. The random range is fixed by the part (0.4-0.8 long, 0.3-0.5 high, 0.3-0.5 wide), not derived from them.' },
    mass: { type: 'number', default: 10, min: 0.5, max: 100, step: 0.5, label: 'Mass (kg)', group: 'Box', desc: 'Mass given to every spawned box, whatever its size.' },
    disable: { type: 'boolean', default: false, label: 'Disabled', desc: 'Stop spawning entirely. The Use action toggles this in pilot mode, so it doubles as a hand stop.' },
    conveyorId: { type: 'partRef', default: '', label: 'Pause when conveyor stopped', desc: 'Interlock: while the named conveyor is stopped, this spawner holds. Wire that conveyor to the PLC and the feed gates itself, with no tag of its own.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', group: 'Comms', desc: 'Expose this part to the PLC. The run tag below does nothing until this is on.' },
    runTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Run tag (spawn only while true)', group: 'Comms', desc: 'Gate the feed from the program. Note this only takes over once a program actually DRIVES the tag - until then the spawner keeps running, so a merely-declared tag is not a stopped feed.' },
  },
  step(ctx) {
    const p = ctx.params
    // hold while a linked conveyor is stopped, or while a controller DRIVES the run tag de-energized
    // (ctx.tagDriven = output ownership; gating on the tag NAME alone would stop the spawner the moment one
    // was typed).
    const stopped = !ctx.conveyorRunning(p.conveyorId) || (p.enableComms && ctx.tagDriven(p.runTag) ? !ctx.readTag(p.runTag) : false)
    if (p.disable || stopped || p.boxesPerMinute <= 0) {
      // held: the interval runs on, floored at zero — see the note at the top. Floored is what makes this safe
      // for an interlock that STUTTERS: at most one box is ever due when the gate reopens, never a burst.
      countdown = Math.max(0, countdown - ctx.dt)
      return
    }
    const period = 60 / p.boxesPerMinute
    // the first box drops on the first eligible tick, not after a full period
    if (!started) { started = true; countdown = 0 }
    countdown -= ctx.dt
    const pal = palette(p.boxColors)
    let n = 0
    while (countdown <= 0 && n < 8) {
      countdown += p.fixedRate ? period : Math.max(ctx.dt, period * (0.5 + ctx.rng()))
      n++
      let color
      if (pal.length > 0) {
        color = p.randomColors ? pal[Math.floor(ctx.rng() * pal.length)] : pal[colorIndex % pal.length]
        colorIndex++
      } else {
        color = hexRgb(p.boxColor)
      }
      const rnd = (i) => SIZE_MIN[i] + ctx.rng() * (SIZE_MAX[i] - SIZE_MIN[i])
      const size = p.randomSize ? [rnd(0), rnd(1), rnd(2)] : [p.length, p.height, p.width]
      ctx.spawn({ size: size, color: color, mass: p.mass, offset: [0, -0.2, 0] })
    }
  },
})

// Diffuse Sensor — a photoeye. Demonstrates sensing (ctx.sense), an emissive detection LED (ctx.lamps), and
// a PLC presence tag. The lens emits a beam along local +Z; the host casts it against cargo each tick and
// hands back the nearest hit.

definePart({
  lamps: ['led'],
  // Declarative snap: the host lands 'at' (the lens front face) on the nearer conveyor guard, pushes the body
  // out by outwardOffset, aims the beam (local +Z) inward across the belt, and fits maxRange to span it.
  snap: {
    mounts: [{ at: [0, 0, 0.037], accepts: 'conveyorGuard', face: 'in', outwardOffset: 0.02, fitRangeParam: 'maxRange' }],
  },
  params: {
    maxRange: { type: 'number', default: 2, min: 0.1, max: 10, step: 0.05, label: 'Max range (m)', desc: 'How far down the beam a target still counts as present. The beam is cast along local +Z, so aim the sensor by rotating it; snapping it onto a conveyor guard fits this range across the lane for you.' },
    showBeam: { type: 'boolean', default: true, label: 'Show beam', desc: 'Draw the beam line in the viewport. A viewing aid only - hiding it does not change what the sensor detects.' },
    normallyClosed: { type: 'boolean', default: false, label: 'Normally closed', desc: 'Invert the output, so the tag reads true when NOTHING is detected. The beam colour still follows the real detection, not the inverted signal.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', desc: 'Expose this part to the PLC. The tag below does nothing until this is on.' },
    tag: { type: 'tag', dir: 'out', stType: 'BOOL', default: '', label: 'PLC tag (presence)', desc: 'Where the photoeye publishes presence for the program to read. Whether true means blocked or clear is set by Normally closed above.' },
  },
  step(ctx) {
    // the beam is cast to its full geometric range; gate the hit on the author's maxRange param
    const s = ctx.sense('lens')
    const present = s.hit && s.distance <= ctx.params.maxRange
    ctx.lamps.led = present // raw presence, not the NC-inverted output
    let out = present
    if (ctx.params.normallyClosed) out = !out // NC: de-energized (no cargo) reads true
    if (ctx.params.enableComms && ctx.params.tag) ctx.writeTag(ctx.params.tag, out)
  },
})

// Pop-up Diverter — a telescoping pneumatic pusher. Three nested arms (part1/part2/partEnd) extend across the
// lane to deflect cargo onto a takeaway conveyor; the leading arm carries the collision box that shoves it.
// Driven by an authored 'diverted' toggle / a hand Use, or — while a PLC program drives its tag (comms on +
// ctx.tagDriven) — the tag. The auto-vs-hand handoff follows output ownership, like a real panel.

const RATIO = { ext1: 0.32, ext2: 0.65, ext3: 1.0 } // each arm's share of the full stroke
let progress = 0 // 0 retracted .. 1 fully extended
let diverted = false
let lastDiverted // adopt the Inspector 'diverted' toggle whenever it changes

definePart({
  interactive: true,
  useParam: 'diverted', // the hand state is the param: a stopped-scene Use commits it (a real design edit)
  joints: ['ext1', 'ext2', 'ext3'],
  lamps: ['red', 'green'], // the housing's two panel lenses (LampRed / LampGreen)
  // Declarative snap onto a conveyor guard: 'at' is the push-side edge (local −Z, the arms' reach direction);
  // face 'out' aims local +Z away from the belt so −Z pushes across it; yOffset 0.2 drops the origin below the
  // belt surface so the arms cross at cargo height; outwardOffset 0.05 clears the guard.
  snap: {
    mounts: [{ at: [0, 0, -1.0635], accepts: 'conveyorGuard', face: 'out', yOffset: 0.2, outwardOffset: 0.05 }],
  },
  params: {
    diverted: { type: 'boolean', default: false, label: 'Diverted', desc: 'Push the blade across the lane to deflect cargo. The Use action toggles it in pilot mode; while a program drives the tag below, that program owns it instead.' },
    divertTime: { type: 'number', default: 0.25, min: 0.05, max: 2, step: 0.01, label: 'Divert time (s)', desc: 'How long the blade takes to travel the full stroke, out or back. Too slow and cargo passes before the blade arrives.' },
    divertDistance: { type: 'number', default: 0.75, min: 0.1, max: 1.5, step: 0.05, label: 'Divert distance (m)', desc: 'How far the blade travels across the lane. Size it so the blade pushes cargo clear of the running surface rather than leaving it straddling the edge.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', desc: 'Expose this part to the PLC. The tag below does nothing until this is on.' },
    // autoWhenDriven: this tag COMMANDS the pusher, so a program driving it owns the device — the pilot prompt
    // shows "In auto - PLC controlled" instead of a dead "Use".
    tag: { type: 'tag', dir: 'in', stType: 'BOOL', autoWhenDriven: true, default: '', label: 'PLC tag (bool: extend the pusher)', desc: 'Extend the pusher from the program. While a program drives this tag it OWNS the diverter, so a hand Use in pilot mode is refused with "In auto - PLC controlled".' },
  },
  step(ctx) {
    // Signal precedence, modelled on a real panel: (1) the tag, while comms are on and an attached program
    // actually drives it (ctx.tagDriven); (2) otherwise the hand signal — the 'diverted' param or a pilot Use.
    if (ctx.params.diverted !== lastDiverted) { diverted = ctx.params.diverted; lastDiverted = ctx.params.diverted }
    if (ctx.used()) diverted = !diverted
    // auto wins by overwriting the hand latch: a press while owned is undone the same tick, and when ownership
    // releases (program detach) the pusher holds its last commanded state.
    if (ctx.params.enableComms && ctx.tagDriven(ctx.params.tag)) diverted = ctx.readTag(ctx.params.tag)
    // the hand latch AFTER the auto gate — what the device is really doing, for the Inspector readout
    ctx.report('diverted', diverted)
    const want = diverted ? 1 : 0
    const step = ctx.dt / Math.max(ctx.params.divertTime, 0.01)
    progress = ctx.approach(progress, want, step)
    const reach = ctx.params.divertDistance * progress
    ctx.joints.ext1 = RATIO.ext1 * reach
    ctx.joints.ext2 = RATIO.ext2 * reach
    ctx.joints.ext3 = RATIO.ext3 * reach
    // Panel indicators, read off the HOME end-of-stroke the way a real pusher's reed switches are: green while
    // the blade is home and the lane is clear, red the moment it leaves — held through the whole travel, out
    // and back, not just at full extension. The desktop original lit green on extend and never drove red at
    // all, which left one lens permanently dead; both lenses carry a state here.
    const home = progress <= 1e-4
    ctx.lamps.green = home
    ctx.lamps.red = !home
  },
})

// Platform — an elevated walkway/storage deck. Purely structural: its length/width/height params
// drive a textured concrete deck (role:'deck'), a steel column/beam frame and a perimeter safety railing
// (parametric geometry + per-link steel colour), and the step does nothing. showSupports adds the OSHA
// middle-column grid + under-deck beams (off → a bare table on 4 corner legs); showRailings toggles the whole
// perimeter railing (rig array enabledParam).

definePart({
  // The deck advertises a 'deck' snap surface: a Stairs flight seats its top against a deck edge and sizes
  // itself to heightParam (the deck's elevation above its own floor).
  snap: { surfaces: [{ kind: 'deck', lengthParam: 'length', widthParam: 'width', heightParam: 'height' }] },
  params: {
    // 'face' handles put resize dots in the viewport on that axis (clamped to the param's min/max); the host
    // reflows the deck/frame/railing parametrically.
    length: { type: 'number', default: 4, min: 0.5, step: 0.1, label: 'Length (m)', handle: { kind: 'face', axis: 'x' }, desc: 'Deck extent along local X. Drag the dot on either end face to resize in the viewport; the frame, railing and columns reflow to match.' },
    width: { type: 'number', default: 4, min: 0.5, max: 20, step: 0.1, label: 'Width (m)', handle: { kind: 'face', axis: 'z' }, desc: 'Deck extent along local Z. Drag the dot on either side face to resize in the viewport.' },
    // deck elevation above the floor — drives the column length. The origin is the deck TOP (the columns hang
    // below it), so rest:'surfaceBelow' makes the host stand the origin `height` above whatever surface is
    // beneath at drop/snap/translate: the columns always reach the floor, and dragging the platform up regrows
    // them.
    height: { type: 'number', default: 2, min: 0.3, max: 8, step: 0.05, rest: 'surfaceBelow', label: 'Height (m)', desc: 'Height of the deck top above whatever it stands on, which is also the column length. The origin is the deck top, so raising the platform regrows the columns to reach the floor rather than leaving them hanging.' },
    color: { type: 'color', default: '#f2bd0f', label: 'Steel color', desc: 'Steel tint of the deck, frame and columns.' },
    showRailings: { type: 'boolean', default: true, label: 'Perimeter railing', desc: 'Guard railing around the deck edge. Turning it off removes the barrier a walking pilot leans on, not just the visual.' },
    showSupports: { type: 'boolean', default: true, label: 'Middle supports', desc: 'Interior columns under a large deck, in addition to the corner ones. Cosmetic on a small platform, which the corners already carry.' },
  },
  step() {},
})

// Blade Stop — a pop-up blade that rises through the belt to stop cargo. The blade sections (middle +
// corners) ride a prismatic 'raise' joint; the housing and the pneumatic cylinders stay static, so the corner
// guide rods sit sheathed inside the cylinders and slide up through them on raise. 'airPressureHeight' is the
// mount height of the whole moving assembly above the housing, so the blade rest top sits at
// airPressureHeight + HOUSING_TOP (−0.05 at the 0.07 default). 'raiseHeight' is an absolute top height, so
// the joint commands raiseHeight − restTop; its 0.06 default matches the stroke the GLB rod length is
// authored for (0.108 m), and raising further slides the rods out of the cylinders. Driven by an authored
// 'active' toggle, or — with comms on — a PLC bool tag.

const RAISE_SECONDS = 0.15 // travel time lowered↔raised
const HOUSING_TOP = -0.12 // housing top pinned under the belt; blade rest top = airPressureHeight + HOUSING_TOP
let raised = null // 0 lowered .. 1 raised; seeded from 'active' on the first step, then chases
let active = false // runtime state — follows the 'active' param and a Use/click (pilot mode)
let lastActive // adopt the Inspector 'active' toggle whenever it changes

definePart({
  interactive: true, // a Use/click raises/lowers the blade
  useParam: 'active', // the hand state is the param: a stopped-scene Use commits it as a real design edit
  joints: ['raise'],
  // Declarative snap: the host aligns the blade stop with a conveyor's track, seats it at the bed surface
  // anchored to the rendered roller grid (so the blade rises in a gap between two rollers), and fits 'width'
  // to the usable bed width — host width minus the frame walls, clamped to the param's range.
  snap: {
    track: { fitWidthParam: 'width' },
  },
  params: {
    width: { type: 'number', default: 1.524, min: 0.1, max: 2, step: 0.05, label: 'Width (m)', desc: 'Blade width across the lane. Size it to span the conveying surface, or cargo rides past the end of the blade.' },
    active: { type: 'boolean', default: false, label: 'Active', desc: 'Raise the blade to stop cargo. The Use action toggles it in pilot mode; while a program drives the tag below, that program owns it instead.' },
    raiseHeight: { type: 'number', default: 0.06, min: 0.02, max: 0.5, step: 0.01, label: 'Raise height (m)', desc: 'How far the blade top stands above the conveying surface once raised - the height of the stop cargo meets. At rest the top parks just below the surface, so raising this lengthens the stroke.' },
    airPressureHeight: { type: 'number', default: 0.07, min: 0, max: 0.12, step: 0.005, label: 'Air pressure height (m)', desc: 'Mount height of the whole moving assembly - pistons, blade and rods together - above the housing. Trim it to sit the mechanism correctly against a particular deck; it shifts the REST position, not the stroke.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', desc: 'Expose this part to the PLC. The tag below does nothing until this is on.' },
    // autoWhenDriven: this tag COMMANDS the blade (the step's auto gate reads it), so a program driving it
    // owns the device — the pilot prompt shows "In auto - PLC controlled" instead of a dead "Use".
    tag: { type: 'tag', dir: 'in', stType: 'BOOL', autoWhenDriven: true, default: '', label: 'PLC tag (bool: raise the blade)', desc: 'Raise the blade from the program. While a program drives this tag it OWNS the blade stop, so a hand Use in pilot mode is refused with "In auto - PLC controlled".' },
  },
  step(ctx) {
    // Signal handoff: the tag commands the blade only while a controller actually drives it (comms on + the
    // tag is an attached program's output — ctx.tagDriven). Any other time the manual signal rules: the
    // 'active' param (adopted when toggled in the Inspector) or a pilot Use/click.
    if (ctx.params.active !== lastActive) { active = ctx.params.active; lastActive = ctx.params.active }
    if (ctx.used()) active = !active
    // auto wins by overwriting the hand latch (bumpless transfer): a press while owned is undone the same
    // tick, and when ownership releases the blade holds its last commanded state.
    if (ctx.params.enableComms && ctx.tagDriven(ctx.params.tag)) active = ctx.readTag(ctx.params.tag)
    // the hand latch AFTER the auto gate — what the device is really doing, for the Inspector readout
    ctx.report('active', active)
    const want = active ? 1 : 0
    if (raised === null) raised = want
    raised = ctx.approach(raised, want, ctx.dt / RAISE_SECONDS)
    const restTop = ctx.params.airPressureHeight + HOUSING_TOP // −0.05 at the default mount
    ctx.joints.raise = (ctx.params.raiseHeight - restTop) * raised // blade top lands exactly at raiseHeight
  },
})

// Chain Transfer — a right-angle transfer (RAT). Cargo normally flows through the bed along the
// part's forward (+X, the main line, like every conveyor); on a pop-up command the chain lanes rise and the bed
// diverts it 90° along −Z (the chains' travel direction, off the side). One `conveys` deck carries cargo; the
// behavior switches its surface velocity between the two world directions (derived from ctx.forward) and lifts the
// chains while diverting — the lift slews at a tween rate, not a one-tick jump. Driven by an authored `raised`
// toggle / a hand Use, or — while a PLC program drives its pop-up tag (comms on + ctx.tagDriven) — the tag. The
// auto-vs-hand handoff follows output ownership, like a real panel.

const RAISE = 0.095 // pop-up stroke, m (travel time is the `raiseTime` param — a real RAT's lift is geared)
let raised = false // runtime state — follows the 'raised' param and a Use/click (pilot mode)
let lastRaised // adopt the Inspector 'raised' toggle whenever it changes
let lift = null // current lift, m; seeded from the authored state on the first step, then chases the target

definePart({
  interactive: true, // a Use/click pops the chains up/down
  useParam: 'raised', // the hand state is the param: a stopped-scene Use commits it (a real design edit)
  joints: ['lift'],
  // Declarative snap: the chain transfer seats onto a roller conveyor's bed by lane parity — odd chain counts
  // centre a lane in a roller gap, even counts on a station. The host adopts its roller pitch into 'distance' and
  // auto-fits 'laneLength' to the host bed width × fitWidthScale (the fitted lane scale.z = width · 0.575/1.524,
  // and the native-length-2 lane ends up 2·scale.z long).
  //
  // targetLocalY RECESSES the deck below the host roller line at rest — like the real machine, whose chains sit
  // in the roller gaps until they pop. It is not cosmetic: this deck conveys, so flush with the bed would put two
  // powered surfaces on one plane, and cargo touching both is braked by whichever is idle (a surface velocity of
  // zero is a stopped belt, not neutral). Down, the host rollers alone carry; the 0.095 m stroke then lifts the
  // load 0.065 m clear of them and the chains take it 90° off the line.
  snap: {
    track: {
      lanes: { countParam: 'chains', pitchParam: 'distance' },
      fitWidthParam: 'laneLength',
      fitWidthScale: 1,
      targetLocalY: -0.03,
    },
  },
  params: {
    chains: { type: 'number', default: 5, min: 1, max: 10, step: 1, label: 'Chains', desc: 'How many chain strands lift between the rollers. More strands spread the load, so a small or floppy carton is less likely to sag between them.' },
    distance: { type: 'number', default: 0.33, min: 0.03, max: 5, step: 0.01, label: 'Lane spacing (m)', desc: 'Centre-to-centre gap between chain strands. Together with the strand count this sets how wide the transfer reaches across the host bed.' },
    laneLength: { type: 'number', default: 2, min: 0.5, max: 3, step: 0.1, label: 'Lane length (m)', desc: 'How far each strand runs in the transfer direction - the stroke available to push product off the main line.' },
    speed: { type: 'number', default: 2, min: -3, max: 3, step: 0.1, label: 'Speed (m/s)', desc: 'How fast the chains carry product sideways once raised. Negative sends it the other way.' },
    raised: { type: 'boolean', default: false, label: 'Raised (divert)', desc: 'Lift the chains above the roller line to take the load off the main lane and drive it sideways. The Use action toggles it in pilot mode; while a program drives the pop-up tag below, that program owns it instead.' },
    // How long the lift takes end to end. It is a real interlock, not decoration: a deck driven through its own
    // stroke is a powered surface travelling sideways while still BELOW the roller line, dragging at the row it is
    // about to lift, so a program has to wait this out before it commands the deck to run.
    // It also has a FLOOR set by the cargo, not by the machine. The lift is a linear tween, so the deck steps
    // straight to RAISE/raiseTime and hands the load that speed; at the top the deck stops and the load does not,
    // carrying on for v²/2g. The default throws cargo ~20 mm, which a packed row survives; halving the time
    // quadruples that, and by ~0.07 s a row is thrown ~94 mm and lands with its packing gone.
    raiseTime: { type: 'number', default: 0.15, min: 0.02, max: 2, step: 0.01, label: 'Pop-up time (s)', desc: 'How long the lift takes end to end. Treat it as a real interlock, not decoration: mid-stroke the deck is a powered surface still BELOW the roller line, dragging at the row it is about to lift, so a program must wait this out before commanding the transfer to run. There is also a floor set by the CARGO - the lift is a linear tween, so at the top the deck stops and the load does not. The default throws product about 20 mm, which a packed row survives; halve the time and it is thrown four times as far, and by about 0.07 s a row lands with its packing gone.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', desc: 'Expose this part to the PLC. The tags below do nothing until this is on.' },
    speedTag: { type: 'tag', dir: 'in', stType: 'REAL', setpointFor: 'speed', default: '', label: 'Speed tag', desc: 'The program commands chain speed here, replacing the Speed field above. Careful: once BOUND this takes over even if no program drives it, and an undriven tag reads 0.' },
    // autoWhenDriven: this tag COMMANDS the pop-up (the step's auto gate reads it), so a program driving it
    // owns the device — the pilot prompt shows "In auto - PLC controlled" instead of a dead "Use".
    popupTag: { type: 'tag', dir: 'in', stType: 'BOOL', autoWhenDriven: true, default: '', label: 'Pop-up tag (true = divert)', desc: 'Raise the chains from the program. While a program drives this tag it OWNS the transfer, so a hand Use in pilot mode is refused with "In auto - PLC controlled".' },
  },
  step(ctx) {
    // Signal handoff, modelled on a real panel: the pop-up tag commands the chains only while a controller actually
    // drives it (comms on + the tag is an attached program's output — ctx.tagDriven). Any other time — comms off,
    // no program, sim stopped — the manual signal rules: the 'raised' param or a pilot Use/click.
    if (ctx.params.raised !== lastRaised) { raised = ctx.params.raised; lastRaised = ctx.params.raised }
    if (ctx.used()) raised = !raised
    // auto wins by overwriting the hand latch (bumpless transfer): a press while owned is undone the same tick, and
    // when ownership releases (program detach) the chains hold their last commanded state.
    if (ctx.params.enableComms && ctx.tagDriven(ctx.params.popupTag)) raised = ctx.readTag(ctx.params.popupTag)
    // the hand latch AFTER the auto gate — what the device is really doing, for the Inspector readout
    ctx.report('raised', raised)
    const speed = ctx.params.enableComms && ctx.params.speedTag ? ctx.readNumber(ctx.params.speedTag) : ctx.params.speed
    ctx.report('speed', speed)
    if (lift === null) lift = raised ? RAISE : 0 // first step: start at the authored state (no spurious slew)
    lift = ctx.approach(lift, raised ? RAISE : 0, (RAISE / Math.max(ctx.params.raiseTime, 0.01)) * ctx.dt)
    ctx.joints.lift = lift
    const f = ctx.forward
    if (raised) {
      // DIVERT: the raised chains carry cargo 90° off the main line — forward rotated +90° about +Y, i.e. out to −Z.
      ctx.setSurfaceVelocity({ x: f.z * speed, y: 0, z: -f.x * speed })
    } else {
      // THROUGH: convey along the part's forward (+X) — the main line.
      ctx.setSurfaceVelocity({ x: f.x * speed, y: 0, z: f.z * speed })
    }
  },
})

// Shape — a parametric primitive: box, cylinder, cone or ramp (geometry-function tier). Sized by length (X),
// width (Z) and height (Y), all three of which carry viewport resize dots; the round shapes take their two
// radii from length/2 and width/2, so a squashed cylinder is an elliptical one and the footprint stays exact.
// Base-origin (the shape sits ON local y=0) so it seats on the floor, a platform deck, or another shape.
//
// Solid by default via collision: 'staticHull' — a convex hull of the emitted vertices, which is EXACT for the
// box and honest for the round/wedge shapes (the 'static' box channel would collide a cylinder as its bounding
// square and a ramp as a full block, so nothing could roll up it). Clear 'Solid' for pure massing/decoration.
// No behavior: inert scenery, never a conveying surface — cargo motion belongs to a real conveyor part.

definePart({
  // No snap declaration on purpose. Ambient face-flush (snap: { flush: true }) is the flag for parts that get
  // tiled, and a wall built from blocks looks like the case for it — but box/pallet/rack each carried it
  // briefly and were REVERTED: snapping to every neighbour on every drop reads as over-eager. The explicit
  // alternatives already cover a block: hold-B Face mode, vertex snap, floor rest. A shape also advertises the
  // four vertical faces of its footprint for 'face' MOUNTS implicitly, so a push button or HMI panel lands on
  // one used as a cabinet/column with nothing declared here.
  params: {
    shape: {
      type: 'enum',
      default: 'box',
      label: 'Shape',
      desc: 'Which primitive is built. All four are sized by the same three dimensions below, so switching kind keeps the footprint you already set.',
      options: [
        { value: 'box', label: 'Box' },
        { value: 'cylinder', label: 'Cylinder' },
        { value: 'cone', label: 'Cone' },
        { value: 'ramp', label: 'Ramp' },
      ],
    },
    // the three face handles = the viewport resize dots (±X length, ±Z width, ±Y height). 'height' is the
    // canonical vertical key the resize write path uses.
    length: { type: 'number', default: 1, min: 0.02, max: 40, step: 0.05, label: 'Length X (m)', handle: { kind: 'face', axis: 'x' }, desc: 'Extent along local X, with a viewport dot on each end face. A round shape takes its X radius from half of this, so a cylinder whose length and width differ is an elliptical one.' },
    width: { type: 'number', default: 1, min: 0.02, max: 40, step: 0.05, label: 'Width Z (m)', handle: { kind: 'face', axis: 'z' }, desc: 'Extent along local Z, with a viewport dot on each side face. A round shape takes its Z radius from half of this.' },
    height: { type: 'number', default: 1, min: 0.02, max: 20, step: 0.05, label: 'Height Y (m)', handle: { kind: 'face', axis: 'y' }, desc: 'Extent along local Y. The shape is BASE-ORIGIN, sitting on local y=0, so it seats flat on the floor or a deck and grows upward.' },
    sides: { type: 'number', default: 20, min: 3, max: 48, step: 1, label: 'Sides', group: 'Shape', desc: 'How many facets go around a cylinder or cone. No effect on a box or a ramp.' },
    color: { type: 'color', default: '#9aa3ad', label: 'Color', desc: 'Surface tint.' },
    solid: { type: 'boolean', default: true, label: 'Solid (blocks cargo)', group: 'Physics', desc: 'Give the shape a collision hull, so cargo and a walking pilot are stopped by it. The hull is exact for all four shapes, which is what lets a ramp actually be walked up rather than colliding as a full block. Clear it for pure massing or decoration.' },
  },
  geometry(g, p) {
    var L = typeof p.length === 'number' && p.length > 0 ? p.length : 1
    var W = typeof p.width === 'number' && p.width > 0 ? p.width : 1
    var H = typeof p.height === 'number' && p.height > 0 ? p.height : 1
    var shape = typeof p.shape === 'string' ? p.shape : 'box'
    var N = Math.max(3, Math.min(48, Math.round(typeof p.sides === 'number' ? p.sides : 20)))

    // WINDING: three derives normals from the faces, so every face below is ordered CCW seen from OUTSIDE
    // (normal = (C-B) x (A-B) for a triangle A,B,C). g.box() already does this; the surface()-built shapes
    // follow the same rule face by face.
    var desc
    if (shape === 'box') {
      desc = g.box([L, H, W], [0, H / 2, 0])
    } else if (shape === 'ramp') {
      // a right triangular prism: the deck rises along +X, from the floor at x=-L/2 to full height at x=+L/2,
      // where a vertical back face closes it. Cargo slides DOWN toward -X.
      var s = g.surface()
      var x0 = -L / 2, x1 = L / 2, z0 = -W / 2, z1 = W / 2
      // low edge (y=0) and high edge (y=H), each with its own verts per face so the edges stay crisp
      var slope = [s.vertex(x0, 0, z0, 0, 0), s.vertex(x0, 0, z1, 1, 0), s.vertex(x1, H, z1, 1, 1), s.vertex(x1, H, z0, 0, 1)]
      s.quad(slope[0], slope[1], slope[2], slope[3]) // sloped deck (up + toward -X)
      var bot = [s.vertex(x0, 0, z0, 0, 0), s.vertex(x1, 0, z0, 1, 0), s.vertex(x1, 0, z1, 1, 1), s.vertex(x0, 0, z1, 0, 1)]
      s.quad(bot[0], bot[1], bot[2], bot[3]) // underside (-Y)
      var back = [s.vertex(x1, 0, z1, 0, 0), s.vertex(x1, 0, z0, 1, 0), s.vertex(x1, H, z0, 1, 1), s.vertex(x1, H, z1, 0, 1)]
      s.quad(back[0], back[1], back[2], back[3]) // vertical back face (+X)
      var sideA = [s.vertex(x0, 0, z0, 0, 0), s.vertex(x1, H, z0, 1, 1), s.vertex(x1, 0, z0, 1, 0)]
      s.triangle(sideA[0], sideA[1], sideA[2]) // -Z flank
      var sideB = [s.vertex(x0, 0, z1, 0, 0), s.vertex(x1, 0, z1, 1, 0), s.vertex(x1, H, z1, 1, 1)]
      s.triangle(sideB[0], sideB[1], sideB[2]) // +Z flank
      desc = s.build()
    } else {
      // cylinder / cone: an N-gon ring of radii (L/2, W/2) about the origin, base on y=0. The barrel shares
      // verts around the ring (so it shades ROUND, not faceted) with a duplicated seam column for the u wrap;
      // the caps get their own verts so the rim stays a hard edge.
      var cone = shape === 'cone'
      var rx = L / 2, rz = W / 2
      var sf = g.surface()
      var ax = function (k) { return ((k % N) / N) * Math.PI * 2 }
      var bx = function (k) { return Math.cos(ax(k)) * rx }
      var bz = function (k) { return Math.sin(ax(k)) * rz }
      if (cone) {
        // flanks: one triangle per segment up to the apex. (A=ring k+1, B=ring k, C=apex) faces outward.
        for (var k = 0; k < N; k++) {
          var a1 = sf.vertex(bx(k + 1), 0, bz(k + 1), (k + 1) / N, 0)
          var a0 = sf.vertex(bx(k), 0, bz(k), k / N, 0)
          var ap = sf.vertex(0, H, 0, (k + 0.5) / N, 1)
          sf.triangle(a1, a0, ap)
        }
      } else {
        // barrel: (A=bottom k+1, B=bottom k, C=top k, D=top k+1) faces outward
        var bot0 = [], top0 = []
        for (var c = 0; c <= N; c++) {
          bot0.push(sf.vertex(bx(c), 0, bz(c), c / N, 0))
          top0.push(sf.vertex(bx(c), H, bz(c), c / N, 1))
        }
        for (var w = 0; w < N; w++) sf.quad(bot0[w + 1], bot0[w], top0[w], top0[w + 1])
        // top cap (+Y): the fan runs BACKWARDS around the ring (a forward fan faces -Y)
        var capT = []
        for (var t = 0; t < N; t++) capT.push(sf.vertex(bx(t), H, bz(t), 0.5 + 0.5 * Math.cos(ax(t)), 0.5 + 0.5 * Math.sin(ax(t))))
        for (var ti = 1; ti < N - 1; ti++) sf.triangle(capT[0], capT[ti + 1], capT[ti])
      }
      // base cap (-Y), shared by both: the forward fan, which faces down (hidden against whatever it rests on)
      var capB = []
      for (var b = 0; b < N; b++) capB.push(sf.vertex(bx(b), 0, bz(b), 0.5 + 0.5 * Math.cos(ax(b)), 0.5 + 0.5 * Math.sin(ax(b))))
      for (var bi = 1; bi < N - 1; bi++) sf.triangle(capB[0], capB[bi], capB[bi + 1])
      desc = sf.build()
    }

    var mp = { desc: desc, role: 'mesh', colorParam: 'color' }
    // Every shape here is convex, so ONE hull is the exact solid (the box's hull is its 8 corners). Solid is
    // opt-out: a massing block someone only wants to LOOK at shouldn't stop the line.
    if (p.solid !== false) mp.collision = 'staticHull'
    return [mp]
  },
  step() {
    // inert scenery — no tags, no motion
  },
})

// Push Button — an illuminated, depressable pushbutton. It reacts to a user "use"/click (ctx.used()),
// depresses the cap into the housing (ctx.setSubPose — a −Z travel, the button front is +Z), lights the cap's
// emissive face (ctx.lamps), and drives a PLC tag. Two modes: momentary (default) holds pressed for a 0.3 s
// pulse of SIM time (not wall-clock); maintained latches on each use. The written output is 'pressed XOR
// normallyClosed' (a normally-closed contact reads true at rest).
//
// The LAMP is its own circuit, not a side effect of the press. On real 22 mm gear the light block is a
// separate module stacked behind the operator with its own terminals and often its own voltage, wired
// independently of the contact blocks - making the lamp echo the press is something you do deliberately by
// strapping a contact to it, not what the device does by itself. So the source is DECLARED ('lampSource'),
// never inferred from whether a tag happens to be bound: follows-press (kept as the default, so a freshly
// placed button still visibly lights), a PLC tag (the acknowledge wiring a real panel uses), always-on (a
// power-on indicator), or unlit (no light block fitted). The old rule - tag if bound, else press - hard-coded
// echo as the fallback, which is the wiring you would least often choose, and it could not express two real
// devices: a plain unlit button, and a lamp lit by anything other than this button's own press.

const PRESS_DEPTH = 0.02 // m, cap travel into the housing
const PULSE_S = 0.3 // momentary hold window, seconds of sim time

let pressed = false
let pulseTicks = 0 // remaining momentary window, in whole sim ticks (exact — no float drift)

definePart({
  interactive: true, // makes the part show a "Use" prompt + routes the click to ctx.used()
  lamps: ['cap'],
  // Declarative snap: the button face-mounts on any part's implicit footprint faces — its back plate lands on
  // the face and slides along it with the drag, front (+Z) looking out. `attach` soft-parents the button
  // under its host on commit, so moving the host carries the button with it.
  snap: {
    mounts: [{ at: [0, 0.09, -0.06], accepts: 'face', face: 'out', attach: true }],
  },
  params: {
    text: { type: 'string', default: 'STOP', label: 'Face label', desc: 'Text rendered onto the cap. Keep it short enough to read at station distance.' },
    buttonColor: { type: 'color', default: '#b3140f', label: 'Button color', desc: 'Tint of the cap, and of the lamp when it lights.' },
    momentary: { type: 'boolean', default: true, label: 'Momentary (else maintained latch)', desc: 'On, each press is a fixed 0.3 s pulse of sim time, like a spring-return start button - so a paused sim holds the pulse rather than letting it expire. Off, the button latches on one press and releases on the next, like a maintained selector.' },
    normallyClosed: { type: 'boolean', default: false, label: 'Normally closed (invert output)', desc: 'Invert the output, so the tag reads true while the button is NOT pressed - the safety convention for a stop button, where a broken wire reads the same as a press.' },
    lampSource: {
      type: 'enum', default: 'press', label: 'Lamp source',
      desc: 'What lights the cap. Follows press echoes this button, the way a contact strapped to the light block would. PLC tag hands the lamp to the program through Lamp tag below - the acknowledge wiring a real panel uses. Always on is a power-on indicator. Unlit is a button with no light block fitted.',
      options: [
        { value: 'press', label: 'Follows press' },
        { value: 'tag', label: 'PLC tag' },
        { value: 'on', label: 'Always on' },
        { value: 'off', label: 'Unlit' },
      ],
    },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', desc: 'Expose this part to the PLC. The tags below do nothing until this is on.' },
    tag: { type: 'tag', dir: 'out', stType: 'BOOL', default: '', label: 'PLC tag (button output)', desc: 'Where the button publishes its press for the program to read. Whether true means pressed or at-rest is set by Normally closed above.' },
    lampTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Lamp tag (bool: PLC lights the cap)', desc: 'Which PLC bool lights the cap, so the program can acknowledge a press rather than just echo it. Read only when Lamp source above is set to PLC tag; left unbound there, the lamp stays dark like an unwired light block.' },
  },
  step(ctx) {
    if (ctx.params.momentary) {
      if (ctx.used()) pulseTicks = Math.ceil(PULSE_S / ctx.dt)
      pressed = pulseTicks > 0
      if (pulseTicks > 0) pulseTicks--
    } else {
      if (ctx.used()) pressed = !pressed
      pulseTicks = 0
    }
    // The lamp runs off its DECLARED source (see the header) - the press is only one of the four wirings,
    // not the fallback. A 'tag' source still passes the comms gate: unbound, or with comms off, it reads
    // dark, exactly like a light block nobody wired. The cap depress follows pressed under every source.
    const comms = ctx.params.enableComms
    const src = ctx.params.lampSource
    const litByTag = comms && !!ctx.params.lampTag && ctx.readTag(ctx.params.lampTag)
    ctx.lamps.cap = src === 'on' ? true : src === 'off' ? false : src === 'tag' ? litByTag : pressed
    ctx.setSubPose('cap', { position: [0, 0, pressed ? -PRESS_DEPTH : 0] })
    if (comms && ctx.params.tag) ctx.writeTag(ctx.params.tag, pressed !== ctx.params.normallyClosed)
  },
})

// Stack Light — a parametric 1-8 segment signal tower. Each segment is an emissive lens lamp; one integer
// bitmask lights them — bit i (LSB = the bottom segment) lights segment i+1, colours cycling bottom-up
// green → amber → red → blue → white. The bitmask comes from a PLC INT tag while a program actually DRIVES it
// (comms on + ctx.tagDriven); any other time the authored 'value' param drives the same lamps, and a viewport
// Use/click increments it, wrapping at 2^segments. Bits above the segment count are masked off.

const LAMPS = ['seg1', 'seg2', 'seg3', 'seg4', 'seg5', 'seg6', 'seg7', 'seg8']
let bumps = 0 // viewport Use increments, added to the authored 'value'

definePart({
  interactive: true, // a pilot-mode Use/click steps the lit pattern
  lamps: LAMPS,
  params: {
    segments: { type: 'number', default: 3, min: 1, max: 8, step: 1, label: 'Segments', desc: 'How many lamp tiers are stacked. Colours are fixed and cycle bottom-up: green, amber, red, blue, white.' },
    value: { type: 'number', default: 1, min: 0, max: 255, step: 1, label: 'Value (bitmask)', desc: 'Which tiers are lit, as a bitmask: bit 0 is the BOTTOM tier, so 1 lights green, 2 lights amber, 3 lights both. Bits above the segment count are masked off. A program driving the tag below replaces this value.' },
    enableComms: { type: 'boolean', default: true, label: 'Enable comms', desc: 'Expose this part to the PLC. The tag below does nothing until this is on.' },
    // autoWhenDriven: this tag COMMANDS the lamps (the step's auto gate reads it), so a program driving it
    // owns the device — the pilot prompt shows "In auto - PLC controlled" instead of a dead "Use".
    tag: { type: 'tag', dir: 'in', stType: 'INT', autoWhenDriven: true, setpointFor: 'value', default: '', label: 'PLC tag (int bitmask)', desc: 'The program writes the lit-tier bitmask here. While it drives the tag it OWNS the light, so the Value field above becomes a read-only readout and a hand Use is refused with "In auto - PLC controlled".' },
  },
  step(ctx) {
    const segs = Math.min(8, Math.max(1, Math.round(ctx.params.segments)))
    if (ctx.used()) bumps++
    const manual = (Math.round(ctx.params.value) + bumps) % (1 << segs)
    // Output ownership (ctx.tagDriven): the tag lights the lamps only while a controller actually drives it —
    // gating on the tag NAME instead would pin the tower to a dead tag the moment one was typed. A ternary,
    // not the actuators' overwrite-the-latch form: 'manual' is derived fresh each tick, so release falls back
    // to the authored pattern instead of freezing the last commanded one (right for an indicator).
    const raw = ctx.params.enableComms && ctx.tagDriven(ctx.params.tag) ? ctx.readNumber(ctx.params.tag) : manual
    const v = raw & ((1 << segs) - 1) // mask to the segment count
    ctx.report('value', v) // the pattern actually lit (masked), which is what 'value' means
    for (let i = 0; i < LAMPS.length; i++) ctx.lamps[LAMPS[i]] = i < segs && ((v >> i) & 1) === 1
  },
})

// Six-Axis robot — a pick-and-place arm. Demonstrates comms-driven motion (enableComms): a PLC handshake
// over the device-IO bus — a command tag selects a waypoint, a rising edge on the execute tag starts the move,
// the done tag reads "not moving" (written every step), and the vacuum tag drives the gripper. With comms off
// the arm holds its authored idle pose and does nothing — like a real robot, it moves only when commanded.

const D2R = Math.PI / 180
// Per-joint travel limits (degrees) — mirrored from the rig manifest's joint min/max.
const JOINT_MIN = [-180,-135,-160,-180,-120,-360]
const JOINT_MAX = [180,135,160,180,120,360]
// Shortest-angle path: the landing angle nearest `from` that is congruent to `to` (mod 360°) —
// so a 350° J6 command turns −10°, not the long way round.
const shortestPath = (from, to) => {
  let diff = ((to - from + 180) % 360) - 180
  if (diff < -180) diff += 360
  return from + diff
}
// Overridden from the Inspector by the 'waypoints' param (its numberList grid, or captured by the editor's rig
// gizmo), which arrives already parsed + validated as number[][] — no JSON.parse, no try/catch, no fallback.
const DEFAULT_POSES = [
  [0, -45, 90, 25, 75, 0],   // 0 home
  [0, -15, 55, 0, 80, 0],    // 1 pick (reach down)
  [110, -15, 55, 0, 80, 0],  // 2 place (swing over)
]

let cur = DEFAULT_POSES[0].slice() // current joint angles (deg)
let target = 0             // pose index
let moving = false
let gripClosed = false
// One scalar drives all six joints (coordinated, never per-joint jitter): the active move's start pose, its
// signed per-joint deltas, the dominant-joint distance (deg), progress along it, and the path speed (deg/s).
let from = DEFAULT_POSES[0].slice()
let span = [0, 0, 0, 0, 0, 0]
let moveLen = 0
let progress = 0
let pathVel = 0
// A comms move reports busy for at least this long, so even a degenerate or sub-blendDeg move shows the PLC a
// real busy window and the Execute/Busy handshake can't miss it at any scan rate.
const MIN_MOVE_SEC = 0.1
let busySec = 0 // seconds since the active comms move was accepted

definePart({
  joints: ['j1', 'j2', 'j3', 'j4', 'j5', 'j6'],
  grippers: ['gripper'],
  lamps: ['vacuumLamp'],
  params: {
    speed: { type: 'number', default: 60, min: 5, max: 180, step: 1, label: 'Joint speed (°/s)', desc: 'Top speed along the joint-space path. All six joints are driven from one path parameter, so they start and arrive together instead of the fastest one finishing early.' },
    accel: { type: 'number', default: 240, min: 20, max: 2000, step: 10, label: 'Joint accel (°/s²)', desc: 'How hard the arm ramps to and from the joint speed. Lower it for a heavier or more delicate payload; a short move may never reach top speed at all.' },
    scale: { type: 'number', default: 1, min: 0.1, max: 10, step: 0.1, label: 'Scale', desc: 'Uniform size multiplier on the whole robot, applied to its collision bodies as well as its appearance - so a scaled arm really does reach further, rather than just looking bigger.' },
    // EOAT (end-of-arm tooling): the resizable vacuum plate. Geometry-only — the rig manifest reads these
    // (plate/rail stretch, cap corners, the cup grid, the grab reach), step() never does. The rigSize handles
    // draw as orange dots in the viewport: select the robot and drag them to resize the tool.
    toolSizeX: { type: 'number', default: 0.5, min: 0.5, max: 3, step: 0.01, label: 'Tool size X (m)', group: 'EOAT', handle: { kind: 'rigSize', link: 'eoat', axis: 'x', frameY: -0.075 }, desc: 'Length of the vacuum plate. The orange dots on the tool itself drag this in the viewport, and they ride the arm, so you can size the tool in whatever pose you are inspecting. Size it to the product you are picking - the plate is also the grab reach.' },
    toolSizeZ: { type: 'number', default: 0.5, min: 0.5, max: 3, step: 0.01, label: 'Tool size Z (m)', group: 'EOAT', handle: { kind: 'rigSize', link: 'eoat', axis: 'z', frameY: -0.075 }, desc: 'Width of the vacuum plate, dragged by the same orange dots on the tool.' },
    cupPitchX: { type: 'number', default: 0.1, min: 0.01, max: 0.5, step: 0.005, label: 'Cup pitch X (m)', group: 'EOAT', desc: 'Centre-to-centre spacing of the suction cups along the plate length. The plate fits as many as the pitch allows, so tightening it adds cups rather than moving them.' },
    cupPitchZ: { type: 'number', default: 0.1, min: 0.01, max: 0.5, step: 0.005, label: 'Cup pitch Z (m)', group: 'EOAT', desc: 'Centre-to-centre spacing of the suction cups across the plate width.' },
    cupMarginX: { type: 'number', default: 0.05, min: 0, max: 0.5, step: 0.005, label: 'Cup margin X (m)', group: 'EOAT', desc: 'Inset from each end of the plate before the first cup, so the grid does not run off the edge.' },
    cupMarginZ: { type: 'number', default: 0.05, min: 0, max: 0.5, step: 0.005, label: 'Cup margin Z (m)', group: 'EOAT', desc: 'Inset from each side of the plate before the first cup.' },
    cupsEnabled: { type: 'boolean', default: true, label: 'Suction cups', group: 'EOAT', desc: 'Draw the cup grid under the plate. Appearance only - the grip itself comes from the vacuum tag, not from the cups being visible.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', desc: 'Expose this robot to the PLC. The tags below do nothing until this is on, and without them the arm just rests at its idle pose.' },
    commandTag: { type: 'tag', dir: 'in', stType: 'INT', default: '', label: 'Command tag (INT: 0=home, 1+=waypoint)', desc: 'Which row of the waypoint table to move to, as an index: 0 is home, 1 the second row and so on. Set it BEFORE pulsing execute. An index past the end of the table is ignored, and the arm stays put rather than guessing.' },
    executeTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Execute tag (rising edge runs the move)', desc: 'Pulse this false-to-true to start the move. It is edge-triggered, so holding it true does NOT repeat - drop it and raise it again for each move.' },
    doneTag: { type: 'tag', dir: 'out', stType: 'BOOL', default: '', label: 'Done tag (true while idle)', desc: 'Handshake back to the program: true whenever the arm is parked and ready for the next command. Wait for it before pulsing execute again, or the edge lands mid-move and is dropped.' },
    gripperTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Vacuum tag', desc: 'Grip or release the load. Read continuously rather than on an edge, so hold it true for the whole carry and drop it only once the load is where it belongs.' },
    waypoints: { type: 'numberList', arity: 6, default: DEFAULT_POSES, label: 'Waypoints ([j1..j6 °]; row 0 = home)', desc: 'The poses this robot knows, one row of six JOINT angles each - not a position in space, so the arm reaches a pose exactly as taught with no ambiguity about elbow or wrist. Row 0 is home, and the command tag indexes into this table. Pose the arm with the viewport gizmo and use Capture Pose to append the row rather than typing angles.' },
    blendWaypoints: { type: 'numberList', arity: 1, default: [], label: 'Blend-through waypoint indices (corner without stopping)', desc: 'Which waypoint indices are VIA points: the arm corners through these carrying its speed instead of braking to a stop, which is what turns a jerky index-and-stop cycle into one flowing motion. Leave pick and place poses OUT of this list - those have to arrive exactly.' },
    blendDeg: { type: 'number', default: 12, min: 0, max: 60, step: 1, label: 'Corner blend (° before a via-point to hand off)', desc: 'How early the arm starts cutting the corner at a via point. Larger rounds the path more and moves it further from the taught pose; the arm also caps it at a third of the current move, so a short leg blends less than you asked for rather than overshooting.' },
    pose: { type: 'numberList', arity: 6, default: [DEFAULT_POSES[0]], label: 'Idle pose ([j1..j6 °])', desc: 'The pose a freshly placed robot rests in, and where one waiting for its first Execute sits. It is the arm you see in a stopped scene, so set it to something that reads as parked rather than mid-cycle.' },
  },
  init(ctx) {
    // Seed the arm at its authored idle pose (the 'pose' param) so a freshly placed robot — and a comms robot
    // waiting for its first Execute — rests where the author trained it. Falls back to home if it is ill-shaped.
    const p = ctx.params.pose
    const idle = Array.isArray(p) && p.length > 0 && p[0].length === 6 ? p[0] : DEFAULT_POSES[0]
    cur = idle.slice()
    from = idle.slice()
  },
  step(ctx) {
    const POSES = ctx.params.waypoints.length ? ctx.params.waypoints : DEFAULT_POSES
    let startMove = false // a fresh move was accepted this tick (rebuild the profile from where we are now)
    if (ctx.params.enableComms) {
      // ctx.rising diffs the begin-of-tick snapshot, so an edge held over the async tag bus can't be lost.
      if (ctx.rising(ctx.params.executeTag) && !moving) {
        const cmd = Math.round(ctx.readNumber(ctx.params.commandTag))
        // an out-of-range command ignores the edge: stay put, done stays true
        if (cmd >= 0 && cmd < POSES.length) {
          target = cmd
          moving = true
          startMove = true
          busySec = 0
        }
      }
      gripClosed = ctx.readTag(ctx.params.gripperTag)
    }

    // Coordinated trapezoidal motion: one accel-limited, speed-capped scalar (progress along the dominant
    // joint) advances and every joint is placed as a linear blend of it, so the six can never oscillate or
    // arrive at different times. A move keeps the path speed it inherited from the previous one, so at a
    // 'blend' via-point (blendWaypoints) the velocity carries through the corner instead of pausing; action
    // poses (pick/place) are not blended, so they brake to an exact stop.
    const speed = ctx.params.speed
    const accel = ctx.params.accel
    const dt = ctx.dt
    const blendThis = ctx.params.enableComms && ctx.params.blendWaypoints.some((r) => r[0] === target)

    if (startMove) {
      const tgt = POSES[target]
      moveLen = 0
      for (let i = 0; i < 6; i++) {
        from[i] = cur[i]
        // shortest-angle wrap, but only when that landing angle stays inside the joint's limits;
        // otherwise fall back to the raw target.
        const wrapped = shortestPath(cur[i], tgt[i])
        const goal = wrapped >= JOINT_MIN[i] && wrapped <= JOINT_MAX[i] ? wrapped : tgt[i]
        span[i] = goal - cur[i]
        const a = Math.abs(span[i])
        if (a > moveLen) moveLen = a
      }
      progress = 0 // keep pathVel: carrying it across the seam is what blends a corner
    }

    const remain = Math.max(moveLen - progress, 0)
    const vStop = Math.sqrt(2 * accel * remain)         // top speed that can still brake to a stop at the end
    const vCap = blendThis ? speed : Math.min(speed, vStop) // via-points skip the stop cap so they flow through
    pathVel = ctx.approach(pathVel, vCap, accel * dt)
    progress += pathVel * dt
    if (progress >= moveLen) { progress = moveLen; if (!blendThis) pathVel = 0 }
    const u = moveLen > 1e-6 ? progress / moveLen : 1
    for (let i = 0; i < 6; i++) cur[i] = from[i] + span[i] * u

    if (moving) busySec += dt

    if (ctx.params.enableComms) {
      // A blend via-point hands off early so the next move overlaps it; an action pose waits for the full stop.
      // The MIN_MOVE_SEC floor keeps a move that would finish inside one PLC scan visible.
      //
      // The hand-off window is capped at a THIRD of the move, and that cap is load-bearing. On a via-point move
      // SHORTER than blendDeg, 'remain <= blendDeg' is already true on its first tick: the arm reports arrived
      // the moment MIN_MOVE_SEC is up, having barely left the pose before it, so the corner the author drew is
      // not rounded — the via-point is skipped outright. A short LIFT-OFF between two long swings is exactly
      // the shape that bites, because that is the one leg whose whole job is height. The demo palletizer's
      // 5.7 deg lift out of the pick handed off 143 mm low and carried the layer through the top course of the
      // stack it was building. The cap leaves a long move blending exactly as before (at the stock 12 deg,
      // anything past 36 deg is untouched) and keeps a short one substantially flown.
      const blendWindow = Math.min(ctx.params.blendDeg, moveLen / 3)
      const arrived = blendThis ? remain <= blendWindow : progress >= moveLen
      if (arrived && busySec >= MIN_MOVE_SEC) moving = false
    }

    ctx.joints.j1 = cur[0] * D2R
    ctx.joints.j2 = cur[1] * D2R
    ctx.joints.j3 = cur[2] * D2R
    ctx.joints.j4 = cur[3] * D2R
    ctx.joints.j5 = cur[4] * D2R
    ctx.joints.j6 = cur[5] * D2R
    ctx.grips.gripper = gripClosed
    ctx.lamps.vacuumLamp = gripClosed // the cups compress off this same signal
    if (ctx.params.enableComms && ctx.params.doneTag) ctx.writeTag(ctx.params.doneTag, !moving)
  },
})

// Pallet — authored EUR-pallet cargo. Demonstrates the cargo geometry kind: the package geometry declares
// { kind: 'cargo', cargoKind: 'pallet' } and the host builds the part as one dynamic physics body at the
// standardized EUR pallet size (1.22 × 0.135 × 1.02 m), rendered through the instanced cargo batch as the
// slatted pallet model. Passive payload: step() is empty.

definePart({
  params: {
    // the colour is a tint over the pallet wood texture
    mass: { type: 'number', default: 20, min: 5, max: 100, step: 1, label: 'Mass (kg)', desc: 'Physical mass of the pallet itself, before anything is stacked on it.' },
    color: { type: 'color', default: '#ffffff', label: 'Color', desc: 'Tint over the pallet wood texture. White leaves it untinted.' },
  },
  step() {
  },
})

// Box — a piece of authored cargo. Demonstrates the cargo geometry kind: the package geometry declares
// { kind: 'cargo', cargoKind: 'box' } and the host builds the part as one dynamic physics body sized/tinted
// from the params below (instanced batch render, gizmo grab, pilot carry, protected from the spawner-cargo
// eviction cap). There is nothing to simulate here: cargo is passive payload, so step() is empty.

definePart({
  params: {
    // size drives both the render scale and the dynamic body's half-extents (centre origin)
    length: { type: 'number', default: 0.6, min: 0.1, max: 1.2, step: 0.05, label: 'Length (m)', desc: 'Extent along local X. Drives the collision body as well as the visual, and the box is centred on its origin.' },
    height: { type: 'number', default: 0.4, min: 0.1, max: 1.2, step: 0.05, label: 'Height (m)', desc: 'Extent along local Y. Drives the collision body as well as the visual.' },
    width: { type: 'number', default: 0.4, min: 0.1, max: 1.2, step: 0.05, label: 'Width (m)', desc: 'Extent along local Z. Drives the collision body as well as the visual.' },
    mass: { type: 'number', default: 10, min: 0.5, max: 100, step: 0.5, label: 'Mass (kg)', desc: 'Physical mass. Heavier cargo is harder for a conveyor to accelerate and pushes lighter cargo out of the way.' },
    color: { type: 'color', default: '#ffffff', label: 'Color', desc: 'Tint over the cardboard texture. White leaves it untinted.' },
  },
  step() {
  },
})

// Pallet Spawner — a hopper that emits EUR pallets. Demonstrates ctx.spawn's pallet kind: a rate timer emits
// a real EUR pallet every 60/palletsPerMinute seconds via ctx.spawn({ kind:'pallet' }); the host creates the
// pallet body at the part's pose. A pilot "Use" toggles the line on/off (a runtime latch, so it resets on
// stop/reload); pallets drop at the exact spawn point (no positional scatter). Optionally gated by a conveyor
// interlock (conveyorId → ctx.conveyorRunning) or a PLC run tag.
//
// A magazine is COMMANDED rather than paced, so the gate RE-ARMS it: every time it is enabled the next pallet
// drops on that first eligible tick and the rate only paces it while it stays enabled. That is what makes the
// usual wiring - a controller pulsing the run tag for less than one period per pallet change - dispense exactly
// one pallet, every time. Carry the countdown across the hold instead and only the FIRST pulse ever dispenses
// (the timer happens to start at zero); each later pulse just takes its own length off a period that never
// reaches zero, so the line silently runs on with no pallet under it.

let countdown = 0 // seconds until the next spawn
let armed = false // drop on the first eligible tick after each enable, not a period later
let usedOff = false

function hexRgb(hex) {
  const h = (hex || '').replace('#', '')
  if (h.length < 6) return [1, 1, 1]
  const v = (i) => { const n = parseInt(h.slice(i, i + 2), 16); return Number.isFinite(n) ? n / 255 : 0.5 }
  return [v(0), v(2), v(4)]
}

definePart({
  interactive: true, // a pilot "Use" toggles the line
  params: {
    palletsPerMinute: { type: 'number', default: 12, min: 0, max: 200, step: 1, label: 'Pallets per minute', desc: 'Feed rate. 0 halts the magazine without disabling the part.' },
    fixedRate: { type: 'boolean', default: true, label: 'Fixed rate (off = ±50% jitter)', desc: 'On, pallets arrive on an exact metronome. Off, each gap is randomised between half and one-and-a-half times the nominal period.' },
    // WHITE = untinted, matching oip.pallet's own default: the colour multiplies the pallet wood model
    // rather than replacing it, so any non-white default makes a dispensed pallet a different colour from
    // every hand-placed one beside it. It used to default to '#8a5a2b', which is why the demo's magazine
    // dropped visibly dark pallets onto a build deck stocked with pale ones.
    palletColor: { type: 'color', default: '#ffffff', label: 'Pallet colour', group: 'Pallet', desc: 'Tint multiplied over the pallet wood model. Leave it white unless you want dispensed pallets to read differently from hand-placed ones beside them.' },
    mass: { type: 'number', default: 25, min: 1, max: 200, step: 1, label: 'Mass (kg)', group: 'Pallet', desc: 'Mass given to every dispensed pallet, before anything is stacked on it.' },
    disable: { type: 'boolean', default: false, label: 'Disabled', desc: 'Stop dispensing entirely. The Use action toggles this in pilot mode, so it doubles as a hand stop.' },
    conveyorId: { type: 'partRef', default: '', label: 'Pause when conveyor stopped', desc: 'Interlock: while the named conveyor is stopped, this spawner holds. Wire that conveyor to the PLC and the feed gates itself, with no tag of its own.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', group: 'Comms', desc: 'Expose this part to the PLC. The run tag below does nothing until this is on.' },
    runTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Run tag (spawn only while true)', group: 'Comms', desc: 'Gate the magazine from the program. Note this only takes over once a program actually DRIVES the tag - until then the spawner keeps running, so a merely-declared tag is not a stopped feed.' },
  },
  step(ctx) {
    const p = ctx.params
    if (ctx.used()) usedOff = !usedOff
    // hold while a linked conveyor is stopped, or while a controller DRIVES the run tag de-energized
    // (ctx.tagDriven = output ownership; gating on the tag NAME alone would brick the spawner the moment one
    // was typed — the hand Use above can only latch it MORE off). Undriven, the authored/hand state rules.
    const stopped = !ctx.conveyorRunning(p.conveyorId) || (p.enableComms && ctx.tagDriven(p.runTag) ? !ctx.readTag(p.runTag) : false)
    if (p.disable || usedOff || stopped || p.palletsPerMinute <= 0) { armed = false; return }
    const period = 60 / p.palletsPerMinute
    // held off = disarmed, so this is the first eligible tick of a fresh command: drop now, then pace
    if (!armed) { armed = true; countdown = 0 }
    countdown -= ctx.dt
    let n = 0
    while (countdown <= 0 && n < 4) {
      countdown += p.fixedRate ? period : Math.max(ctx.dt, period * (0.5 + ctx.rng()))
      n++
      ctx.spawn({ kind: 'pallet', color: hexRgb(p.palletColor), mass: p.mass, offset: [0, -0.2, 0] })
    }
  },
})

// Fence — a safety barrier: yellow posts auto-spaced along the length (each with a cap) + a black wire-mesh
// grid (a frame rectangle + vertical/horizontal wires) filling every span — not a solid slab. Demonstrates a
// rig dressed by procedural geometry: geometry() emits the mesh (render-only); the hidden full-span 'barrier'
// rig link is the collision. Length/height-parametric (both with viewport resize dots) + per-surface colour.

// fixed dimensions (m)
var POST = 0.06, MAX_SPACING = 1.5, FRAME = 0.03, WIRE = 0.008, SPACING = 0.1
var CAP_H = 0.03, CAP_FP = POST * 1.08, INSET = 0.08

definePart({
  // End-to-end chaining (declarative SnapChain, docs/part-snap-chain.md): a fence extends collinearly off
  // another fence-family barrier's nearer end, or forms a 90-degree L-corner sharing ONE post — the corner
  // handshake toggles the omitPost* booleans so the shared post draws once. Group 'barrierFence' is shared
  // with the Safety Gate (they chain together); guard rails are their own group and never mix. reach 1 m is
  // the fence family's tight engage distance (SNAP_FENCE_VISIBLE_THRESHOLD).
  snap: { chain: { group: 'barrierFence', lengthParam: 'length', reach: 1, omitStartParam: 'omitPostStart', omitEndParam: 'omitPostEnd' } },
  params: {
    // both sizes are viewport-editable: a 'face' handle puts a resize dot on that axis's faces (docs/part-gizmos.md).
    // X is centre-origin (the opposite end holds); Y is base-origin, so the +Y dot drags the top and the base stays put.
    // The floor is a FILLER PANEL, not a usable run. A guard line is only closed where it meets the machine,
    // and the piece that closes it is whatever the leftover measures — commonly a few hundred mm, as where the
    // demo cell's north run returns to the case line (a 0.48 m slot, so 0.40 m of fence). At 0.5 no fence could
    // shut that at all and the param quietly clamped, which reads as a guarded cell with a person-sized hole in
    // it. 0.2 is where a panel stops being one: the two end posts leave 0.12 of mesh between them.
    length: { type: 'number', default: 4, min: 0.2, step: 0.1, label: 'Length (m)', handle: { kind: 'face', axis: 'x' }, desc: 'Fence run length along local +X. Drag the dot on either end face to resize in the viewport; short runs are legitimate filler panels where a guard line meets a machine.' },
    height: { type: 'number', default: 2, min: 0.5, max: 4, step: 0.1, label: 'Height (m)', handle: { kind: 'face', axis: 'y' }, desc: 'Panel height. The base stays on the floor and the top face moves, so the viewport dot drags the top.' },
    postColor: { type: 'color', default: '#f2bd0f', label: 'Post color', desc: 'Post tint.' },
    meshColor: { type: 'color', default: '#0d0d0d', label: 'Mesh color', desc: 'Tint of the frame and the wire panel it holds.' },
    omitPostStart: { type: 'boolean', default: false, label: 'Omit start post', group: 'Posts', desc: 'Suppress the post at local -X so a snapped neighbour draws the shared one instead. Snapping sets this for you.' },
    omitPostEnd: { type: 'boolean', default: false, label: 'Omit end post', group: 'Posts', desc: 'Suppress the post at local +X so a snapped neighbour draws the shared one instead. Snapping sets this for you.' },
  },
  geometry(g, p) {
    var length = typeof p.length === 'number' && p.length > 0 ? p.length : 4
    var height = typeof p.height === 'number' && p.height > 0 ? p.height : 2
    var omitStart = p.omitPostStart === true
    var omitEnd = p.omitPostEnd === true
    var box = function (cx, cy, cz, sx, sy, sz) { return g.box([sx, sy, sz], [cx, cy, cz]) }
    var posts = []
    var mesh = []
    // fill [xa,xb] x [yb,yt] with a frame rectangle + a wire grid
    var panel = function (xa, xb, yb, yt) {
      var cx = (xa + xb) / 2, cy = (yb + yt) / 2, w = xb - xa, h = yt - yb
      mesh.push(box(cx, yb, 0, w, FRAME, FRAME), box(cx, yt, 0, w, FRAME, FRAME))
      mesh.push(box(xa, cy, 0, FRAME, h, FRAME), box(xb, cy, 0, FRAME, h, FRAME))
      var cols = Math.max(1, Math.round(w / SPACING)), colStep = w / cols
      for (var i = 1; i < cols; i++) mesh.push(box(xa + i * colStep, cy, 0, WIRE, h, WIRE))
      var rows = Math.max(1, Math.round(h / SPACING)), rowStep = h / rows
      for (var j = 1; j < rows; j++) mesh.push(box(cx, yb + j * rowStep, 0, w, WIRE, WIRE))
    }
    var hl = length / 2
    var numSpans = Math.max(1, Math.ceil(length / MAX_SPACING))
    var span = length / numSpans
    var inset = Math.min(INSET, height * 0.1)
    var yb = inset, yt = height - inset
    var margin = POST * 0.5 + 0.01
    var postXs = []
    for (var s0 = 0; s0 <= numSpans; s0++) postXs.push(-hl + s0 * span)
    for (var i = 0; i < postXs.length; i++) {
      if ((i === 0 && omitStart) || (i === numSpans && omitEnd)) continue // a snapped neighbour supplies the corner post
      var x = postXs[i]
      posts.push(box(x, height / 2, 0, POST, height, POST))
      mesh.push(box(x, height + CAP_H / 2, 0, CAP_FP, CAP_H, CAP_FP))
    }
    for (var s = 0; s < numSpans; s++) {
      var xa = postXs[s] + margin, xb = postXs[s + 1] - margin
      if (xb > xa) panel(xa, xb, yb, yt)
    }
    var parts = []
    if (posts.length) parts.push({ desc: g.merge.apply(g, posts), material: 'postMetal', colorParam: 'postColor' })
    parts.push({ desc: g.merge.apply(g, mesh), material: 'meshMetal', colorParam: 'meshColor' })
    return parts
  },
  step() {},
})

// Safety Gate — a swinging interlock gate: a black wire-mesh leaf carrying a red e-stop handle, hinged at the
// -X post between yellow posts, swinging to 'openAngle' at 'openSpeed' (°/s). Demonstrates procedural geometry
// on a MOVING link — geometry() emits the posts/caps on the rig root and tags the leaf mesh to the swinging
// 'hinge' frame (MeshPart.link), so it rides the joint; the hidden 'leaf' box is the collision. A PLC input
// (safety-door switch): it writes 'open XOR normallyClosed' and never reads a tag.

const D2R = Math.PI / 180
let angle = 0 // current swing angle (rad)
let flip = false // viewport Use toggles: XORed with the authored 'open' param

definePart({
  // End-to-end chaining (declarative SnapChain, docs/part-snap-chain.md): the gate butts into a fence run or
  // corners with one, sharing the corner post via the omitPost* handshake. Group 'barrierFence' is shared with
  // the Fence — a gate is a door IN a fence line — at the fence family's tight 1 m reach.
  snap: { chain: { group: 'barrierFence', lengthParam: 'length', reach: 1, omitStartParam: 'omitPostStart', omitEndParam: 'omitPostEnd' } },
  interactive: true,
  useParam: 'open', // the hand state is the param: a stopped-scene Use commits it (a real design edit)
  joints: ['swing'],
  params: {
    length: { type: 'number', default: 1, min: 0.5, max: 6, step: 0.05, label: 'Width (m)', desc: 'Gate width, hinge post to latch post. Size it to the gap you are closing in the fence line.' },
    open: { type: 'boolean', default: false, label: 'Open', desc: 'Swing the leaf open. The Use action toggles it in pilot mode, which is how someone walks through the guard line.' },
    openAngle: { type: 'number', default: 110, min: -180, max: 180, step: 1, label: 'Open angle (°)', desc: 'How far the leaf swings about the hinge when open. Negative angles swing it the other way, for a gate that has to open into the aisle.' },
    openSpeed: { type: 'number', default: 180, min: 10, max: 720, step: 5, label: 'Open speed (°/s)', desc: 'How fast the leaf travels between shut and the open angle.' },
    normallyClosed: { type: 'boolean', default: false, label: 'Normally closed (invert signal)', desc: 'Invert the signal this gate publishes, so the tag reads true while the gate is SHUT - the safety convention, where a broken wire and an open gate look the same to the program. Affects the comms output only, never the visuals.' },
    postColor: { type: 'color', default: '#f2bd0f', label: 'Post color', group: 'Colors', desc: 'Post tint.' },
    meshColor: { type: 'color', default: '#0d0d0d', label: 'Mesh color', group: 'Colors', desc: 'Tint of the leaf frame and the panel it holds.' },
    handleColor: { type: 'color', default: '#c91717', label: 'Handle color', group: 'Colors', desc: 'Tint of the emergency release handle.' },
    omitPostStart: { type: 'boolean', default: false, label: 'Omit start post', group: 'Posts', desc: 'Suppress the post at local -X so a snapped neighbour draws the shared one instead. Snapping sets this for you.' },
    omitPostEnd: { type: 'boolean', default: false, label: 'Omit end post', group: 'Posts', desc: 'Suppress the post at local +X so a snapped neighbour draws the shared one instead. Snapping sets this for you.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', group: 'Comms', desc: 'Expose this part to the PLC. The tag below does nothing until this is on.' },
    tag: { type: 'tag', dir: 'out', stType: 'BOOL', default: '', label: 'PLC tag (bool: gate signal out)', group: 'Comms', desc: 'Where the gate publishes its state for the program to read. Whether true means open or shut is set by Normally closed above.' },
  },
  geometry(g, p) {
    var length = typeof p.length === 'number' && p.length > 0 ? p.length : 1
    var omitStart = p.omitPostStart === true
    var omitEnd = p.omitPostEnd === true
    // fixed dimensions (m)
    var H = 2.0, POST = 0.06, GAP = 0.04, INSET = 0.08
    var FRAME = 0.03, WIRE = 0.008, SPACING = 0.1, CAP_H = 0.03, CAP_FP = POST * 1.08
    var HS = 0.035, STANDOFF = 0.07, HANDLE_H = 1.0
    var PLATE_X = 0.22, PLATE_Y = 0.14, PLATE_Z = 0.03
    var box = function (cx, cy, cz, sx, sy, sz) { return g.box([sx, sy, sz], [cx, cy, cz]) }
    var hl = length / 2
    var posts = [], caps = [], leaf = [], handle = []

    // omit an end post where a snapped corner neighbour supplies it
    if (!omitStart) { posts.push(box(-hl, H / 2, 0, POST, H, POST)); caps.push(box(-hl, H + CAP_H / 2, 0, CAP_FP, CAP_H, CAP_FP)) }
    if (!omitEnd) { posts.push(box(hl, H / 2, 0, POST, H, POST)); caps.push(box(hl, H + CAP_H / 2, 0, CAP_FP, CAP_H, CAP_FP)) }

    // Leaf wire-mesh + e-stop in the hinge link's local frame: the hinge pivots at the −X post, so its local x
    // runs GAP..length−GAP and y runs INSET..H−INSET. Tagged link:'hinge' to ride the swing joint — tagging the
    // hidden 'leaf' box (same pose, collision-only) instead would inherit its invisibility.
    var xa = GAP, xb = length - GAP, yb = INSET, yt = H - INSET
    var cx = (xa + xb) / 2, cy = (yb + yt) / 2, w = xb - xa, h = yt - yb
    leaf.push(box(cx, yb, 0, w, FRAME, FRAME), box(cx, yt, 0, w, FRAME, FRAME))
    leaf.push(box(xa, cy, 0, FRAME, h, FRAME), box(xb, cy, 0, FRAME, h, FRAME))
    var cols = Math.max(1, Math.round(w / SPACING)), colStep = w / cols
    for (var i = 1; i < cols; i++) leaf.push(box(xa + i * colStep, cy, 0, WIRE, h, WIRE))
    var rows = Math.max(1, Math.round(h / SPACING)), rowStep = h / rows
    for (var j = 1; j < rows; j++) leaf.push(box(cx, yb + j * rowStep, 0, w, WIRE, WIRE))

    // e-stop mounting plate on the latch side (+X), mesh colour
    var hy = Math.min(Math.max(HANDLE_H, yb + PLATE_Y), Math.max(yb + PLATE_Y, yt - PLATE_Y))
    leaf.push(box(xb - PLATE_X / 2, hy, 0, PLATE_X, PLATE_Y, PLATE_Z))

    // e-stop grip: a horizontal bar standing off each face on two standoff legs (handle colour)
    var gripX0 = xb - PLATE_X + HS, gripX1 = xb - HS
    var gripLen = Math.max(gripX1 - gripX0, HS), gripCx = (gripX0 + gripX1) / 2
    var legLen = Math.max(STANDOFF - PLATE_Z / 2, HS), legZ = PLATE_Z / 2 + legLen / 2
    for (var si = 0; si < 2; si++) {
      var side = si === 0 ? 1 : -1
      handle.push(box(gripCx, hy, side * STANDOFF, gripLen, HS, HS))
      handle.push(box(gripX0, hy, side * legZ, HS, HS, legLen))
      handle.push(box(gripX1, hy, side * legZ, HS, HS, legLen))
    }

    var parts = []
    if (posts.length) parts.push({ desc: g.merge.apply(g, posts), material: 'postMetal', colorParam: 'postColor' })
    if (caps.length) parts.push({ desc: g.merge.apply(g, caps), material: 'meshMetal', colorParam: 'meshColor' })
    parts.push({ desc: g.merge.apply(g, leaf), link: 'hinge', material: 'meshMetal', colorParam: 'meshColor' })
    parts.push({ desc: g.merge.apply(g, handle), link: 'hinge', material: 'handleMetal', colorParam: 'handleColor' })
    return parts
  },
  step(ctx) {
    if (ctx.used()) flip = !flip
    const open = ctx.params.open !== flip
    const target = open ? ctx.params.openAngle * D2R : 0
    angle = ctx.approach(angle, target, ctx.params.openSpeed * D2R * ctx.dt)
    ctx.joints.swing = angle
    // safety-door-switch output — normallyClosed inverts the signal only, not the motion
    if (ctx.params.enableComms && ctx.params.tag) ctx.writeTag(ctx.params.tag, open !== ctx.params.normallyClosed)
  },
})

// Floor Marking — painted floor bands (geometry-function tier). Five styles (solid / hazard stripes / dashed /
// border / stripes) as flat two-colour geometry, all quads in the part-local x ∈ [−L/2, L/2], z ∈ [−W/2, W/2]
// rectangle: geometry(g, p) partitions it into bands and returns one MeshPart per colour, each tinted live from
// a 'color' param via MeshPart.colorParam. Render-only — no collision, no conveying; the part is pure paint.

definePart({
  // Edge-to-edge tiling (declarative SnapEdges): the host slides same-group rectangles flush along the shared
  // edge, with corner-flush alignment when one overhangs a smaller neighbour.
  snap: { edges: { group: 'floorMarking', lengthParam: 'length', widthParam: 'width', cornerFlush: true } },
  params: {
    // 'face' handles = viewport resize dots (±X length, ±Z width)
    length: { type: 'number', default: 2, min: 0.1, step: 0.1, label: 'Length (m)', handle: { kind: 'face', axis: 'x' }, desc: 'Extent along local X. Drag the dot on either end face to resize in the viewport.' },
    width: { type: 'number', default: 8, min: 0.1, max: 30, step: 0.1, label: 'Width (m)', handle: { kind: 'face', axis: 'z' }, desc: 'Extent along local Z. Drag the dot on either side face to resize in the viewport.' },
    style: {
      type: 'enum',
      default: 'hazard',
      label: 'Style',
      desc: 'Which pattern is painted into the rectangle. Border draws an outline only and leaves the interior bare floor; every other style covers the whole footprint.',
      options: [
        { value: 'solid', label: 'Solid' },
        { value: 'hazard', label: 'Hazard stripes' },
        { value: 'dashed', label: 'Dashed' },
        { value: 'border', label: 'Border' },
        { value: 'stripes', label: 'Stripes' },
      ],
    },
    stripeSize: { type: 'number', default: 0.3, min: 0.05, max: 2, step: 0.05, label: 'Stripe size (m)', group: 'Pattern', desc: "Width of one stripe or dash (the pattern repeats every two of them). Bands are phased from this part's own origin, so two markings laid end to end won't necessarily line up." },
    borderWidth: { type: 'number', default: 0.1, min: 0.02, max: 1, step: 0.01, label: 'Border width (m)', group: 'Pattern', desc: 'Width of the border band. Only the Border style draws one.' },
    // alpha:true accepts #rrggbbaa colours — the picker gains an A slider; a fully-transparent secondary cuts
    // its bands out (see secOn below).
    primaryColor: { type: 'color', default: '#f2b705', label: 'Primary color', group: 'Colors', alpha: true, desc: 'The base colour: the solid fill, the first hazard/stripe band, the dashed field, the border itself. Always painted, and always opaque - the bands are geometry, so partial alpha does nothing here.' },
    secondaryColor: { type: 'color', default: '#1a1a1a', label: 'Secondary color', group: 'Colors', alpha: true, desc: 'The alternating colour: the second hazard/stripe band and the dashes. Take its alpha all the way to zero to drop those bands entirely and leave bare floor between the primary ones; any other alpha paints opaque. Unused by Solid and Border.' },
  },
  // Bands never overlap in-plane — only the dashed style layers, and its dashes float clear of the field.
  geometry(g, p) {
    var L = typeof p.length === 'number' && p.length > 0 ? p.length : 2
    var W = typeof p.width === 'number' && p.width > 0 ? p.width : 8
    var s = typeof p.stripeSize === 'number' && p.stripeSize > 0 ? p.stripeSize : 0.3
    var bw = typeof p.borderWidth === 'number' && p.borderWidth > 0 ? p.borderWidth : 0.1
    var style = typeof p.style === 'string' ? p.style : 'hazard'
    var Y = 0.01 // lift above the floor plane (m) so the bands don't z-fight it
    var x0 = -L / 2, x1 = L / 2, z0 = -W / 2, z1 = W / 2
    var prim = g.surface()
    var sec = g.surface()
    // a fully-transparent secondary (#rrggbb00) emits no secondary bands, so the floor shows through the gaps.
    // Partial alpha is not supported — bands are opaque geometry.
    var secOn = !(typeof p.secondaryColor === 'string' && /^#[0-9a-fA-F]{6}00$/.test(p.secondaryColor))

    // clip a convex [x, z] polygon to the half-plane f(pt) >= 0 (Sutherland–Hodgman, one edge)
    function clip(poly, f) {
      var out = []
      for (var i = 0; i < poly.length; i++) {
        var a = poly[i], b = poly[(i + 1) % poly.length]
        var fa = f(a), fb = f(b)
        if (fa >= 0) out.push(a)
        if (fa >= 0 !== fb >= 0) {
          var t = fa / (fa - fb)
          out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t])
        }
      }
      return out
    }
    // fan a convex [x, z] polygon into a surface as an up-facing flat face at height y
    function emit(sfc, poly, y) {
      if (poly.length < 3) return
      var idx = []
      for (var i = 0; i < poly.length; i++) idx.push(sfc.vertex(poly[i][0], y, poly[i][1], poly[i][0], poly[i][1]))
      for (var k = 1; k < poly.length - 1; k++) sfc.triangle(idx[0], idx[k], idx[k + 1])
    }
    // an axis-aligned band rectangle, clamped to the marking; CCW seen from above (+Y normal)
    function rectPoly(rx0, rz0, rx1, rz1) {
      rx0 = Math.max(rx0, x0); rz0 = Math.max(rz0, z0); rx1 = Math.min(rx1, x1); rz1 = Math.min(rz1, z1)
      if (rx1 - rx0 < 1e-6 || rz1 - rz0 < 1e-6) return null
      return [[rx0, rz0], [rx0, rz1], [rx1, rz1], [rx1, rz0]]
    }
    var rect = rectPoly(x0, z0, x1, z1)

    if (style === 'solid') {
      emit(prim, rect, Y)
    } else if (style === 'hazard') {
      // diagonal hazard bands over the sum x+z, period 2s: primary for the first s, secondary for the next.
      // Band phase is part-local, so two abutting markings don't necessarily align.
      var k0 = Math.floor((x0 + z0) / (2 * s)), k1 = Math.ceil((x1 + z1) / (2 * s))
      for (var k = k0; k < k1; k++) {
        var a = 2 * s * k
        var pBand = clip(clip(rect, function (pt) { return pt[0] + pt[1] - a }), function (pt) { return a + s - pt[0] - pt[1] })
        emit(prim, pBand, Y)
        var sBand = clip(clip(rect, function (pt) { return pt[0] + pt[1] - (a + s) }), function (pt) { return a + 2 * s - pt[0] - pt[1] })
        if (secOn) emit(sec, sBand, Y)
      }
    } else if (style === 'dashed') {
      // a primary field with secondary dashes (length s, period 2s) down the centre fifth of the short axis,
      // running along the long axis. Dashes float 0.6 mm over the field (two layers can't z-fight).
      emit(prim, rect, Y)
      var longX = L >= W
      var a0 = longX ? x0 : z0, a1 = longX ? x1 : z1
      var c0 = longX ? z0 + 0.4 * W : x0 + 0.4 * L, c1 = longX ? z0 + 0.6 * W : x0 + 0.6 * L
      var dk0 = Math.floor(a0 / (2 * s)), dk1 = Math.ceil(a1 / (2 * s))
      for (var dk = dk0; dk < dk1; dk++) {
        var d0 = Math.max(2 * s * dk, a0), d1 = Math.min(2 * s * dk + s, a1)
        if (d1 - d0 < 1e-6) continue
        var dash = longX ? rectPoly(d0, c0, d1, c1) : rectPoly(c0, d0, c1, d1)
        if (secOn) emit(sec, dash, Y + 0.0006)
      }
    } else if (style === 'border') {
      // outline only — four non-overlapping bands (two full-width sides + two ends between them), interior open
      var b = Math.min(bw, L / 2, W / 2)
      emit(prim, rectPoly(x0, z0, x0 + b, z1), Y)
      emit(prim, rectPoly(x1 - b, z0, x1, z1), Y)
      emit(prim, rectPoly(x0 + b, z0, x1 - b, z0 + b), Y)
      emit(prim, rectPoly(x0 + b, z1 - b, x1 - b, z1), Y)
    } else {
      // 'stripes' — alternating bands over the long axis measured from the edge, period 2s: primary for the
      // first s, secondary for the next.
      var sLongX = L >= W
      var sa0 = sLongX ? x0 : z0, sa1 = sLongX ? x1 : z1
      var n = Math.ceil((sa1 - sa0) / (2 * s))
      for (var sk = 0; sk < n; sk++) {
        var p0 = sa0 + 2 * s * sk, p1 = Math.min(p0 + s, sa1), q1 = Math.min(p0 + 2 * s, sa1)
        var pBand2 = sLongX ? rectPoly(p0, z0, p1, z1) : rectPoly(x0, p0, x1, p1)
        emit(prim, pBand2, Y)
        if (q1 - p1 > 1e-6) {
          var sBand2 = sLongX ? rectPoly(p1, z0, q1, z1) : rectPoly(x0, p1, x1, q1)
          if (secOn) emit(sec, sBand2, Y)
        }
      }
    }

    // an empty surface (e.g. solid's secondary) is dropped by the host's normalizer
    return [
      { desc: prim.build(), role: 'mesh', colorParam: 'primaryColor' },
      { desc: sec.build(), role: 'mesh', colorParam: 'secondaryColor' },
    ]
  },
  step() {
    // pure paint — nothing to do
  },
})

// Turntable Conveyor — a rotating redirect table: rotate → align → convey. The deck is a kinematic disc on
// the 'rotate' revolute joint; the hidden `conveys` lane box on top of it is the cargo surface. While slewing,
// the lane's linear velocity is held at 0 and cargo is spun with the platter instead: an arc surface-velocity
// field about the pivot, the same rotational field the deck imparts by friction. Once settled, the lane
// conveys at `speed` along the deck's current forward — the conveys body is static and its surface velocity
// world-space, so the direction is recomputed from the deck angle every tick. By default the deck slews to the
// manual `deckAngleDeg` and holds there — an angled cross-feed you orient from the Inspector, not a
// self-runner. With comms (enableComms) a PLC commands the target angle instead.

const D2R = Math.PI / 180

// wrap a degree angle/delta into (−180, 180] — the shortest-path wrap convention
const wrap180 = (a) => { let r = a % 360; if (r > 180) r -= 360; else if (r <= -180) r += 360; return r }

let angle = 0      // current deck angle (deg), kept wrapped in (−180, 180]
let seeded = false
// THE PLATTER CARRIES ITS LOAD — carry phase: 0 idle · 1 arming · 2 carrying · 3 arrived (still held).
// A real turntable holds its load in static contact: the acceleration it demands is an order of magnitude
// under the friction limit, so nothing slips, and the load reaches the outfeed at exactly the deck angle
// (which is the whole reason the machine exists — a few degrees out jams a wrapper or a truck pattern).
// Dragging cargo with the arc surface-velocity field cannot promise that: the field commands a RATE, so any
// slip is integrated into the final ANGLE and is never corrected. Measured before this: the same pallet came
// off 0.7° out one cycle and 4° the next, and on a bare plate it sometimes stopped tracking altogether while
// the deck spun under it. So the deck GRIPS what stands on it for the duration of the turn.
// The two extra phases exist for the two ENDS of the turn, each worth a step of skew if fumbled:
//   1 arming  — the grip closes while the deck stands STILL, so the host captures the load at the angle the
//               deck is actually at; closing and turning in the same tick bakes in one step of rotation.
//   3 arrived — the deck has landed and stays held for that tick, so its final pose is driven onto the load
//               before the release (a release tick drives nothing, it just lets go).
let carry = 0
// Drive RAMP. No real turntable steps to full speed in one tick — a VFD is given an acceleration time (this
// is literally a drive parameter), and the deck eases up to speed and back down onto the index. RAMP_S is
// that acceleration time: seconds from standstill to the commanded top speed, so the acceleration itself
// scales with whatever speed the author sets. `rate` is the current angular rate in °/s, ramped toward the
// commanded top speed and braked in time to land on the target without overshoot (a trapezoidal profile).
const RAMP_S = 0.5
let rate = 0

definePart({
  joints: ['rotate'],
  grippers: ['deck'],
  params: {
    width: { type: 'number', default: 1.524, min: 0.3, max: 3, step: 0.05, label: 'Lane width (m)', desc: 'Width of the conveying lane across the deck. Size it to the conveyors it indexes between, since the lane is what actually carries product once the deck has settled.' },
    // deck height above the floor — drives the leg length. rest:'surfaceBelow' lets the host auto-fill it from
    // the surface beneath at drop/snap/translate, so raising the turntable regrows the legs to reach.
    standHeight: { type: 'number', default: 0.95, min: 0.1, max: 3, step: 0.01, rest: 'surfaceBelow', label: 'Stand height (m)', desc: 'Height of the deck above whatever is beneath it, which sets the leg length. The host fills this in when you drop or snap the turntable, so raising it regrows the legs to reach.' },
    speed: { type: 'number', default: 1, min: -3, max: 3, step: 0.1, label: 'Speed (m/s)', desc: 'How fast the lane conveys once the deck has SETTLED at its target angle. While the deck is still slewing the lane carries nothing forward - product just rides round with the platter - so this only applies between moves.' },
    deckAngleDeg: { type: 'number', default: 0, min: -180, max: 180, step: 15, label: 'Deck angle (°)', desc: 'Target angle for the deck, which then slews to it and holds. This is the whole control surface when comms are off: an angled cross-feed you aim from the Inspector rather than a self-runner. A program commands it through the angle tag below instead.' },
    // TOP speed, reached through the ramp below. 20°/s is a 90° index in ~5 s including both ramps, which is
    // where real units sit (3-6 s); the old 45°/s default was about double industry practice, and combined
    // with an instant start it demanded more of the deck than any real drive delivers.
    rotationSpeedDeg: { type: 'number', default: 20, min: 1, max: 360, step: 5, label: 'Rotation speed (°/s, top)', desc: 'TOP slew rate, reached through a fixed acceleration ramp rather than instantly. The default indexes 90 degrees in about 5 seconds including both ramps, which is where real units sit - winding it much higher asks more of the deck than a real drive delivers, and product slides.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', desc: 'Expose this part to the PLC. The tags below do nothing until this is on.' },
    angleTag: { type: 'tag', dir: 'in', stType: 'REAL', setpointFor: 'deckAngleDeg', default: '', label: 'Target-angle tag (REAL °)', desc: 'The program commands the deck angle here, replacing the Deck angle field above. On the first scan the part SEEDS the tag with the authored angle, so a program that has not written yet does not slam the deck to zero.' },
    speedTag: { type: 'tag', dir: 'in', stType: 'REAL', setpointFor: 'speed', default: '', label: 'Speed tag (REAL m/s)', desc: 'The program commands lane speed here, replacing the Speed field above. Careful: once BOUND this takes over even if no program drives it, and an undriven tag reads 0.' },
    doneTag: { type: 'tag', dir: 'out', stType: 'BOOL', default: '', label: 'Done tag (true once settled)', desc: 'Handshake back to the program: true once the deck has stopped at its target angle. Wait on this before commanding the lane to run, or product is pushed at a deck still turning under it.' },
  },
  step(ctx) {
    // Setpoint precedence, same shape as every other comms part: the angle tag replaces the authored
    // deckAngleDeg while comms are on AND a tag is actually bound. Gating on 'seeded' alone (as this did)
    // meant comms-on with an EMPTY angleTag read tag "" — always 0 — so the deck ignored its authored angle
    // and slewed to zero, while the Inspector went on showing the angle it had abandoned.
    const comms = ctx.params.enableComms
    const bound = comms && ctx.params.angleTag
    let target
    if (bound) {
      // seed-write once from the deck's authored angle so the PLC sees a sensible initial target; after that
      // the tag is read-only here (the PLC owns it).
      if (!seeded) ctx.writeNumber(ctx.params.angleTag, ctx.params.deckAngleDeg)
      target = seeded ? ctx.readNumber(ctx.params.angleTag) : ctx.params.deckAngleDeg
    } else {
      target = ctx.params.deckAngleDeg
    }
    seeded = true
    // shortest-path slew: wrap the delta to (−180, 180] so 350° from 0 takes the −10° road
    const topRate = ctx.params.rotationSpeedDeg
    const accel = topRate / RAMP_S // °/s², so the ramp TIME is fixed and the rate scales with the setting
    const d = wrap180(target - angle)
    const pending = Math.abs(d) > 1e-6
    // advance the carry phase (see the note by `carry`), then move only while actually carrying
    if (carry === 3) { carry = 0; rate = 0 }
    else if (carry === 0 && pending) carry = 1
    else if (carry === 1) carry = 2
    if (carry === 2) {
      // trapezoidal profile: brake once the remaining travel is only just enough to stop in (v²/2a),
      // otherwise keep accelerating toward the top rate. Landing snaps the last sub-step so a decaying
      // rate can't crawl at the target forever.
      const remaining = Math.abs(d)
      const brakeIn = (rate * rate) / (2 * accel)
      rate = remaining <= brakeIn ? Math.max(0, rate - accel * ctx.dt) : Math.min(topRate, rate + accel * ctx.dt)
      const stepNow = rate * ctx.dt
      if (remaining <= stepNow || remaining <= 1e-6) { angle = wrap180(angle + d); carry = 3; rate = 0 }
      else angle = wrap180(angle + Math.sign(d) * stepNow)
    }
    const settled = !pending || carry === 3
    ctx.grips.deck = carry !== 0
    ctx.joints.rotate = angle * D2R // continuous revolute — the wrap keeps the command inside ±π
    // once settled, convey along the deck's current forward — ctx.forward (the part's world +X) rotated by the
    // deck angle; while slewing, spin resting cargo with the platter via the arc field instead
    const speed = comms && ctx.params.speedTag ? ctx.readNumber(ctx.params.speedTag) : ctx.params.speed
    ctx.report('speed', speed)
    ctx.report('deckAngleDeg', target)
    if (settled) {
      const c = Math.cos(angle * D2R)
      const s = Math.sin(angle * D2R)
      const f = ctx.forward
      ctx.setSurfaceVelocity({ x: (f.x * c + f.z * s) * speed, y: 0, z: (f.z * c - f.x * s) * speed })
    } else {
      // the RAMPED rate, not the top speed: this field is the fallback for anything the deck grip did not
      // take (cargo that arrived mid-turn), and it should describe what the plate is actually doing
      ctx.setArcSurfaceVelocity({ center: { x: ctx.position.x, z: ctx.position.z }, omega: Math.sign(d) * rate * D2R })
    }
    if (comms && ctx.params.doneTag) ctx.writeTag(ctx.params.doneTag, settled)
  },
})

// Fork-lift AGV — a mobile pick-and-place vehicle. Demonstrates root motion: it moves its own base with
// ctx.drive(forward, turn) and reads its live pose back via ctx.position / ctx.forward to steer toward
// waypoints, each [worldX, worldZ, headingDeg, forkHeight]. It is driven over comms (enableComms) by a PLC
// handshake; with comms off the AGV stays parked (forks down, beacon dark) — it drives only when commanded.
// It also animates the cosmetic dressing joints each tick: the four wheels roll from the commanded travel and
// the mast piston tracks the lift at half rate.
//
// The fork HEIGHT rides in the waypoint rather than in a second command, because a truck that picks off a 1 m
// deck and sets that load on a 1.6 m rack beam has to meet each surface at its own height, and the row that
// says where to stand is the natural place to say how high to hold the tines. Sending the same spot twice at
// two heights is therefore a lift or a lower, standing still. The fork tag is left with one job: GRAB or
// RELEASE, both of which happen where the tines are (see the grip note in step).

const D2R = Math.PI / 180
const WHEEL_RADIUS = 0.125 // AGV.glb wheel radius (core AGV_WHEEL_RADIUS)
const PISTON_LIFT_RATIO = 0.5 // core AGV_PISTON_LIFT_RATIO
const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v)
// signed shortest angle from a to b, in (−π, π]
const angDiff = (a, b) => Math.atan2(Math.sin(b - a), Math.cos(b - a))
// wrap an accumulating angle into (−π, π] so the wheel joints never leave their clamp range
const wrapPi = (a) => Math.atan2(Math.sin(a), Math.cos(a))

// Author-editable via the 'waypoints' numberList grid, which arrives already parsed + validated as number[][]
// — no JSON.parse, no silent fallback; each row is exactly [x, z, deg, fork height m] (a missing height cell
// pads 0, i.e. forks down).
const DEFAULT_WP = [
  [0, 0, 0, 0],   // 0 home (forks down)
  [4, 0, 0, 1],   // 1 pick — drive to the feed with the tines at deck height (the fork tag grabs there)
  [4, 4, 90, 1],  // 2 carry across the cell
  [0, 4, 180, 0], // 3 place — set the load back down, facing back (the fork tag releases there)
]

let wpIdx = 0
let phase = 'turn1'    // turn1 (face the target) → drive (straight) → turn2 (final heading) → act (forks)
let reversing = false  // this move is a straight BACK-OUT — no facing turn, so nothing swings
let liftAt = 0         // live fork height, m
let held = false       // grip state, latched at the commanded height (see step)
let moving = false
let wheelAngle = 0     // shared wheel roll angle (visual)

definePart({
  joints: ['lift', 'piston', 'wheelLF', 'wheelRF', 'wheelLR', 'wheelRR'],
  grippers: ['gripper'],
  lamps: ['beacon'],
  params: {
    driveSpeed: { type: 'number', default: 1, min: 0.1, max: 5, step: 0.1, label: 'Drive speed (m/s)', desc: 'How fast the truck travels between waypoints.' },
    turnSpeed: { type: 'number', default: 90, min: 10, max: 360, step: 1, label: 'Turn speed (°/s)', desc: 'How fast it pivots on the spot. Every move turns to face the target, drives, then turns to the waypoint heading, so this sets much of the cycle time on short hops.' },
    liftSpeed: { type: 'number', default: 1.2, min: 0.1, max: 5, step: 0.1, label: 'Fork lift speed (m/s)', desc: 'How fast the tines raise and lower to the height the waypoint asks for.' },
    maxLiftHeight: { type: 'number', default: 3, min: 0.1, max: 8, step: 0.1, label: 'Max fork height (m)', desc: 'Ceiling on the tines, whatever a waypoint asks for. Set it to the top beam of the racking the truck actually serves.' },
    reverseRange: { type: 'number', default: 3, min: 0, max: 20, step: 0.5, label: 'Back-out range (m; 0 = always turn)', desc: 'How close a target has to be for the truck to REVERSE to it instead of turning round. It only applies when the target is behind, within this range, and at roughly the heading already held - the shape of withdrawing tines from a rack bay, where turning would swing two metres of fork through the uprights. Set 0 to always turn and drive forward.' },
    enableComms: { type: 'boolean', default: false, label: 'Enable comms', desc: 'Expose this truck to the PLC. The tags below do nothing until this is on, and without them the truck simply parks at home.' },
    commandTag: { type: 'tag', dir: 'in', stType: 'INT', default: '', label: 'Command tag (INT: 0=home, 1+=waypoint)', desc: 'Which row of the waypoint table to drive to, as an index: 0 is home, 1 the second row and so on. Set it BEFORE pulsing execute. An index past the end of the table is ignored, and the truck stays put rather than guessing.' },
    executeTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Execute tag (rising edge runs the move)', desc: 'Pulse this false-to-true to start the move. It is edge-triggered, so holding it true does NOT repeat - drop it and raise it again for each move. An edge arriving mid-move is ignored.' },
    doneTag: { type: 'tag', dir: 'out', stType: 'BOOL', default: '', label: 'Done tag (true while idle)', desc: 'Handshake back to the program: true whenever the truck is parked and ready for the next command. Wait for it before pulsing execute again, or the edge lands mid-move and is dropped.' },
    forkTag: { type: 'tag', dir: 'in', stType: 'BOOL', default: '', label: 'Fork tag (true grabs, false releases)', desc: 'Clamp or release whatever is sitting on the tines. It is read continuously rather than on an edge, so hold it true for the whole carry and drop it only once the load is where it belongs.' },
    waypoints: { type: 'numberList', arity: 4, default: DEFAULT_WP, label: 'Waypoints ([x, z, °, fork height m]; row 0 = home)', desc: 'The stops this truck knows, one row each: where to stand in scene X and Z, which way to face, and how high to carry the tines. Row 0 is home, and the command tag indexes into this table - so adding a row is how the program gets somewhere new to send it.' },
  },
  step(ctx) {
    const WP = ctx.params.waypoints.length ? ctx.params.waypoints : DEFAULT_WP

    // live pose (ctx.position/forward reflect a drive command the following tick)
    const px = ctx.position.x, pz = ctx.position.z
    const fx = ctx.forward.x, fz = ctx.forward.z
    const yaw = Math.atan2(-fz, fx)
    const turnRate = ctx.params.turnSpeed * D2R
    const ANG_TOL = 1.5 * D2R, POS_TOL = 0.06

    if (ctx.params.enableComms) {
      // ctx.rising diffs the begin-of-tick snapshot, so an edge held over the async tag bus can't be missed
      if (ctx.rising(ctx.params.executeTag) && !moving) {
        const cmd = Math.round(ctx.readNumber(ctx.params.commandTag))
        // an out-of-range command ignores the edge: stay put, done stays true
        if (cmd >= 0 && cmd < WP.length) {
          wpIdx = cmd; phase = 'turn1'; moving = true
          // BACK OUT rather than turn round, when the target is behind, close, and asks for the heading already
          // held. That is the shape of exactly one move — withdrawing the tines from a rack bay — and turning to
          // face it would swing two metres of fork through the uprights and through the load just set down.
          // Anything beyond reverseRange is a haul rather than a withdrawal, so it drives forward as before.
          const t = WP[wpIdx]
          const bx = t[0] - px, bz = t[1] - pz
          reversing = ctx.params.reverseRange > 0 &&
            Math.hypot(bx, bz) <= ctx.params.reverseRange &&
            bx * fx + bz * fz < 0 &&
            Math.abs(angDiff(yaw, (t[2] || 0) * D2R)) <= 20 * D2R
        }
      }
    }

    const tgt = WP[wpIdx] || DEFAULT_WP[0]
    const tx = tgt[0], tz = tgt[1], tyaw = (tgt[2] || 0) * D2R
    const forksUp = ctx.params.enableComms ? ctx.readTag(ctx.params.forkTag) : false
    const dx = tx - px, dz = tz - pz
    const dist = Math.hypot(dx, dz)

    let fwdCmd = 0, turnCmd = 0
    if (moving && reversing) {
      // straight back on the heading already held: steer out any drift, roll back until the target is abeam
      const behind = -(dx * fx + dz * fz)
      const e = angDiff(yaw, tyaw)
      if (Math.abs(e) > ANG_TOL) turnCmd = clamp(e / ctx.dt, -turnRate, turnRate)
      if (behind > POS_TOL) fwdCmd = -Math.min(ctx.params.driveSpeed, behind / ctx.dt)
      else if (Math.abs(e) <= ANG_TOL) phase = 'act'
    } else if (moving) {
      if (phase === 'turn1') {
        if (dist <= POS_TOL) phase = 'turn2'
        else {
          const travel = Math.atan2(-dz, dx)
          const e = angDiff(yaw, travel)
          if (Math.abs(e) <= ANG_TOL) phase = 'drive'
          else turnCmd = clamp(e / ctx.dt, -turnRate, turnRate)
        }
      }
      if (phase === 'drive') {
        if (dist <= POS_TOL) phase = 'turn2'
        else {
          const travel = Math.atan2(-dz, dx)
          turnCmd = clamp(angDiff(yaw, travel) / ctx.dt, -turnRate, turnRate) // keep aligned while rolling
          fwdCmd = Math.min(ctx.params.driveSpeed, dist / ctx.dt) // never overshoot the waypoint in one tick
        }
      }
      if (phase === 'turn2') {
        const e = angDiff(yaw, tyaw)
        if (Math.abs(e) <= ANG_TOL) phase = 'act'
        else turnCmd = clamp(e / ctx.dt, -turnRate, turnRate)
      }
    }
    ctx.drive(fwdCmd, turnCmd)

    // wheels roll from the commanded travel (the drive applies fwdCmd exactly, so command = actual)
    wheelAngle = wrapPi(wheelAngle + (fwdCmd * ctx.dt) / WHEEL_RADIUS)
    ctx.joints.wheelLF = wheelAngle
    ctx.joints.wheelRF = wheelAngle
    ctx.joints.wheelLR = wheelAngle
    ctx.joints.wheelRR = wheelAngle

    // the fork height is the WAYPOINT's, clamped to the mast's travel
    const liftTgt = clamp(tgt[3] || 0, 0, ctx.params.maxLiftHeight)
    liftAt = ctx.approach(liftAt, liftTgt, ctx.params.liftSpeed * ctx.dt)
    const forksSettled = Math.abs(liftAt - liftTgt) < 1e-3
    ctx.joints.lift = liftAt
    ctx.joints.piston = liftAt * PISTON_LIFT_RATIO
    // Grab and let go WHERE THE TINES ARE, never on the command itself. A grip captures the load's pose RELATIVE
    // to the tines at the moment it closes, so closing while they are still travelling makes the load ride that
    // gap for the whole trip, and opening mid-stroke lets it go in mid-air. Latching the tag on arrival instead
    // means the tines meet the load where it stands, carry it, and set it on whatever deck or beam they were
    // sent to before letting go — which is also just what a fork truck does.
    if (forksSettled) held = forksUp
    ctx.grips.gripper = held
    ctx.lamps.beacon = moving

    if (phase === 'act' && forksSettled) moving = false
    if (ctx.params.enableComms && ctx.params.doneTag) ctx.writeTag(ctx.params.doneTag, !moving)
  },
})

// Storage Rack — a pallet rack: an upright frame carrying evenly-spaced shelves. Demonstrates
// array links: numShelves + shelfSpacing drive a stacked shelf array and the derived frame height (a mulParam
// product); enableAutoPoles fills the footprint with a poleInterval pole grid. Purely structural — the params
// reshape the rig, the step does nothing. Cargo rests on each shelf (a collision slab).

definePart({
  params: {
    // 'face' handles put resize dots in the viewport on that axis (clamped to the param's min/max);
    // bayParam/bayGateParam snap the drag to whole poleInterval bays while auto-poles are on.
    length: { type: 'number', default: 2.8, min: 0.5, step: 0.1, label: 'Width (m)', handle: { kind: 'face', axis: 'x', bayParam: 'poleInterval', bayGateParam: 'enableAutoPoles' }, desc: 'Frame width along local X. Drag the dot on either end face to resize in the viewport; while auto poles are on that drag snaps to whole bays, so the rack always ends on an upright.' },
    depth: { type: 'number', default: 1.4, min: 0.4, max: 4, step: 0.1, label: 'Depth (m)', handle: { kind: 'face', axis: 'z', bayParam: 'poleInterval', bayGateParam: 'enableAutoPoles' }, desc: 'Frame depth along local Z. Drag the dot on either side face to resize in the viewport.' },
    numShelves: { type: 'number', default: 4, min: 1, max: 10, step: 1, label: 'Shelves', desc: 'How many shelf levels sit above the floor. With the spacing below, this is what sets the total height.' },
    shelfSpacing: { type: 'number', default: 1.6, min: 0.5, max: 3, step: 0.05, label: 'Shelf spacing (m)', desc: 'Vertical gap between shelf levels. Leave room for the tallest load you mean to store, plus the truck reaching it.' },
    enableAutoPoles: { type: 'boolean', default: true, label: 'Auto poles', desc: 'Fill the footprint with a grid of uprights and load beams. Off leaves four corner posts only, which reads as a light shelving unit rather than pallet racking.' },
    poleInterval: { type: 'number', default: 1.4, min: 0.5, max: 3, step: 0.1, label: 'Pole interval (m)', desc: 'Centre-to-centre spacing of the uprights, applied along both width and depth. This is also the bay size a viewport resize snaps to.' },
    shelfColor: { type: 'color', default: '#cc8033', label: 'Shelf color', desc: 'Tint of the shelf decking.' },
    frameColor: { type: 'color', default: '#4d4d4d', label: 'Frame color', desc: 'Tint of the uprights and load beams.' },
  },
  step() {},
})

// Stairs — an industrial access flight. Demonstrates array links + parametric geometry + a
// constant-slope rotation: 'numSteps' closed-riser steps rise up-and-forward by a constant rise/run (a
// diagonal array `step`), carried by two sloped side stringers, with a full handrail — a post at every step +
// sloped top & mid rails + a bottom newel — that showHandrails toggles off. Invisible guard colliders line
// both open sides (slope + landing) so a walker can't step off. Two-tone: textured concrete treads/risers you
// walk on (the treads collide), steel structure tinted by `color`. Purely structural — the params reshape the
// rig, the step does nothing.

definePart({
  // Seat the flight against a platform deck edge, sizing numSteps to the deck height: the host platform
  // advertises its deck via a 'deck' snap surface (with a heightParam), the flight's foot lands on the deck's
  // floor, and its top landing end butts the nearest edge (landingDepth — the whole flight outside the deck).
  snap: { stairMount: { accepts: 'deck', widthParam: 'width', stepsParam: 'numSteps', reach: 3, landingDepth: 0.6 } },
  params: {
    numSteps: { type: 'number', default: 11, min: 2, max: 40, step: 1, label: 'Steps', desc: 'Number of steps in the flight, which is what sets both its rise and its run: the slope is fixed at the standard 0.178 m rise over a 0.28 m tread, so a flight grows along the diagonal rather than getting steeper. Count the steps you need to reach the deck.' },
    width: { type: 'number', default: 1.2, min: 0.4, max: 4, step: 0.05, label: 'Width (m)', desc: 'Tread width across local Z.' },
    showHandrails: { type: 'boolean', default: true, label: 'Handrails', desc: 'Handrails up both sides of the flight.' },
    color: { type: 'color', default: '#f2bd0f', label: 'Steel color', desc: 'Steel tint of the treads, stringers and rails.' },
  },
  step() {},
})

stProgram:
FUNCTION_BLOCK PalletTruck
VAR_INPUT
  Enable   : BOOL;
  Request  : BOOL;
  Idle     : BOOL;
  Grant    : BOOL;
  PickBase : INT;
  WayBase  : INT;
  WayOut   : INT;
  WayMid   : INT;
  WayIn    : INT;
  DropBase : INT;
  Slots    : INT;
END_VAR
VAR_OUTPUT
  Cmd  : INT;
  Exec : BOOL;
  Fork : BOOL;
  Want : BOOL;
  Step : INT;
  Slot : INT;
  Done : BOOL;
END_VAR
VAR
  Moving  : BOOL;
  Started : BOOL;
  Send    : INT;
  wi      : INT;
  Lift    : TON;
  Drop    : TON;
END_VAR

IF Moving THEN
  IF NOT Idle THEN Started := TRUE; END_IF;
  IF Started THEN Exec := FALSE; END_IF;
  IF Started AND Idle THEN Moving := FALSE; END_IF;
END_IF;

Lift(IN := Enable AND (Step = 20) AND NOT Moving, PT := T#600ms);
Drop(IN := Enable AND (Step = 30) AND NOT Moving, PT := T#600ms);

Send := -1;
IF Enable THEN
  CASE Step OF
    0:  IF Request AND Idle AND NOT Done THEN Want := TRUE;         Step := 5;  END_IF;
    5:  IF Grant THEN wi := 0;                                      Step := 6;  END_IF;
    6:  IF NOT Moving THEN
          IF wi < WayOut THEN  Send := WayBase + wi; wi := wi + 1;
          ELSE                 Send := PickBase;                    Step := 12; END_IF;
        END_IF;
    12: IF NOT Moving THEN     Send := PickBase + 1;                Step := 14; END_IF;
    14: IF NOT Moving THEN     Send := PickBase + 2;                Step := 16; END_IF;
    16: IF NOT Moving THEN     Send := PickBase + 3;                Step := 20; END_IF;
    20: IF NOT Moving THEN
          Fork := TRUE;
          IF Lift.Q THEN       Send := PickBase + 4; wi := 0;       Step := 22; END_IF;
        END_IF;
    22: IF NOT Moving THEN
          IF wi < WayMid THEN  Send := WayBase + WayOut + wi; wi := wi + 1;
          ELSE                 Send := DropBase + 4 * Slot;         Step := 24; END_IF;
        END_IF;
    24: IF NOT Moving THEN     Send := DropBase + 4 * Slot + 1;     Step := 25; END_IF;
    25: IF NOT Moving THEN     Send := DropBase + 4 * Slot + 2;     Step := 30; END_IF;
    30: IF NOT Moving THEN
          Fork := FALSE;
          IF Drop.Q THEN       Send := DropBase + 4 * Slot + 3; wi := 0; Step := 32; END_IF;
        END_IF;
    32: IF NOT Moving THEN
          IF wi < WayIn THEN   Send := WayBase + WayOut + WayMid + wi; wi := wi + 1;
          ELSE
            Slot := Slot + 1;
            IF Slot > Slots - 1 THEN Slot := Slots - 1; Done := TRUE; END_IF;
            Send := 0;                                             Step := 40;
          END_IF;
        END_IF;
    40: IF NOT Moving THEN      Want := FALSE;                      Step := 0;  END_IF;
  END_CASE;
END_IF;
IF Send >= 0 THEN
  Cmd := Send; Exec := TRUE; Moving := TRUE; Started := FALSE;
END_IF;
END_FUNCTION_BLOCK

VAR_INPUT
  Start      : BOOL;
  Stop       : BOOL := TRUE;
  Guard      : BOOL := TRUE;
  BoxAtEye   : BOOL;
  RowReady   : BOOL;
  LayerReady : BOOL;
  ArmIdle    : BOOL;
  TurnDone   : BOOL := TRUE;
  TurnEye    : BOOL;
  LaneAFull  : BOOL;
  LaneBFull  : BOOL;
  Agv1Idle   : BOOL := TRUE;
  Agv2Idle   : BOOL := TRUE;
END_VAR
VAR_OUTPUT
  Infeed     : REAL;
  RowForm    : REAL;
  ShiftSpeed : REAL;
  SpawnRun   : BOOL;
  Turn       : BOOL;
  Shift      : BOOL;
  ArmCmd     : INT;
  ArmExec    : BOOL;
  ArmVac     : BOOL;
  PalletOut  : REAL;
  TurnRun    : REAL;
  TurnCmd    : REAL;
  LaneA      : REAL;
  LaneB      : REAL;
  Agv1Cmd    : INT;
  Agv1Exec   : BOOL;
  Agv1Fork   : BOOL;
  Agv2Cmd    : INT;
  Agv2Exec   : BOOL;
  Agv2Fork   : BOOL;
  PalletFeed : BOOL;
  RunLamp    : BOOL;
  Tower      : INT;
  (* Cases counted at the release eye since the run started. An OUTPUT because something outside the program
     reads it: the scene's infeed annotation puts it on the layout. *)
  Cases      : DINT;
END_VAR
VAR
  running    : BOOL := TRUE;

  InfeedSpeed : REAL := 1.0;
  RunSpeed   : REAL := 1.0;
  ShiftRate  : REAL := 1.0;
  safe       : BOOL;

  Arrival    : R_TRIG;
  rowPhase   : INT;
  rowsPushed : INT;
  turnedFirst : BOOL;
  thisRowTurned : BOOL;
  rowTarget  : INT;
  rowSent    : INT;
  RowPacked  : TON;
  rowDone    : BOOL;
  shifting   : BOOL;
  ShiftPulse : TON;
  Raised     : TON;
  Pushing    : R_TRIG;
  Shifted    : R_TRIG;
  layerDone  : BOOL;

  Step       : INT;
  OutStep    : INT := 100;
  Moving     : BOOL;
  Started    : BOOL;
  PickDwell  : TON;
  PlaceDwell : TON;
  FeedPulse  : TON;
  TurnSettle : TON;

  layerIdx   : INT;
  placeIdx   : INT;
  palletFull : BOOL := TRUE;
  picking    : BOOL;

  LineSpeed  : REAL := 0.4;

  laneSel    : INT := 1;
  outRun     : BOOL;
  laneRun    : BOOL;

  Truck1     : PalletTruck;
  Truck2     : PalletTruck;
  Zone       : INT;
  A1Step     : INT;
  A1Slot     : INT;
  A1Done     : BOOL;
  A2Step     : INT;
  A2Slot     : INT;
  A2Done     : BOOL;
END_VAR

running := (Start OR running) AND Stop;
safe := running AND Guard;

turnedFirst := (layerIdx MOD 2) = 1;
IF turnedFirst THEN
  thisRowTurned := rowPhase = 0;
ELSE
  thisRowTurned := rowPhase = 1;
END_IF;
IF thisRowTurned THEN
  rowTarget := 3;
ELSE
  rowTarget := 2;
END_IF;
Arrival(CLK := BoxAtEye);
IF Arrival.Q THEN
  rowSent := rowSent + 1;
  (* Cumulative production count, on the SAME edge the row logic already uses - a real line counts product
     at a photo-eye, not by asking the machine that made it. DINT, not INT: at 30 cases/min a 16-bit count
     would wrap after about 18 hours of running, which is exactly the kind of number nobody checks. *)
  Cases := Cases + 1;
END_IF;

RowPacked(IN := RowReady AND (rowSent >= rowTarget) AND NOT shifting AND NOT picking, PT := T#1000ms);

rowDone := RowPacked.Q AND (rowsPushed < 2) AND NOT shifting;
shifting := (rowDone OR shifting) AND NOT ShiftPulse.Q;

ShiftPulse(IN := shifting, PT := T#2000ms);

Raised(IN := shifting, PT := T#200ms);

Pushing(CLK := shifting);
IF Pushing.Q AND (rowsPushed = 0) THEN
  rowPhase := 1;
  rowSent := 0;
END_IF;
Shifted(CLK := ShiftPulse.Q);
IF Shifted.Q THEN
  rowsPushed := rowsPushed + 1;
  IF rowsPushed >= 2 THEN
    rowSent := 0;
  END_IF;
END_IF;

layerDone := (rowsPushed >= 2) AND LayerReady;

IF Moving THEN
  IF NOT ArmIdle THEN Started := TRUE; END_IF;
  IF Started THEN ArmExec := FALSE; END_IF;
  IF Started AND ArmIdle THEN Moving := FALSE; END_IF;
END_IF;
PickDwell(IN := safe AND (Step = 20) AND NOT Moving, PT := T#400ms);
PlaceDwell(IN := safe AND (Step = 50) AND NOT Moving, PT := T#400ms);

FeedPulse(IN := PalletFeed, PT := T#1000ms);
TurnSettle(IN := OutStep = 115, PT := T#1200ms);

IF safe THEN
  CASE Step OF
    0:  picking := FALSE;
        IF layerDone AND NOT palletFull THEN
          placeIdx := layerIdx;
          ArmCmd := 1; ArmExec := TRUE; Moving := TRUE; Started := FALSE; picking := TRUE; Step := 10;
        END_IF;
    10: IF NOT Moving THEN
          ArmCmd := 2; ArmExec := TRUE; Moving := TRUE; Started := FALSE; Step := 20;
        END_IF;
    20: IF NOT Moving THEN
          ArmVac := TRUE;
          IF PickDwell.Q THEN
            ArmCmd := 1; ArmExec := TRUE; Moving := TRUE; Started := FALSE; Step := 30;
          END_IF;
        END_IF;
    30: IF NOT Moving THEN
          rowPhase := 0;
          rowSent := 0;
          rowsPushed := 0;
          picking := FALSE;
          layerIdx := layerIdx + 1;
          IF layerIdx >= 3 THEN layerIdx := 0; END_IF;
          ArmCmd := 3; ArmExec := TRUE; Moving := TRUE; Started := FALSE; Step := 40;
        END_IF;
    40: IF NOT Moving THEN
          ArmCmd := 4 + placeIdx; ArmExec := TRUE; Moving := TRUE; Started := FALSE; Step := 50;
        END_IF;
    50: IF NOT Moving THEN
          ArmVac := FALSE;
          IF PlaceDwell.Q THEN
            ArmCmd := 3; ArmExec := TRUE; Moving := TRUE; Started := FALSE; Step := 60;
          END_IF;
        END_IF;
    60: IF NOT Moving THEN
          IF placeIdx >= 2 THEN
            IF OutStep = 0 THEN
              palletFull := TRUE;
              OutStep := 100;
              ArmCmd := 0; ArmExec := TRUE; Moving := TRUE; Started := FALSE; Step := 0;
            END_IF;
          ELSE
            ArmCmd := 0; ArmExec := TRUE; Moving := TRUE; Started := FALSE; Step := 0;
          END_IF;
        END_IF;
  END_CASE;

  CASE OutStep OF
    100: IF (laneSel = 0) AND NOT LaneAFull THEN
           TurnCmd := 0.0; OutStep := 105;
         ELSIF (laneSel = 1) AND NOT LaneBFull THEN
           TurnCmd := 0.0; OutStep := 105;
         ELSIF NOT LaneAFull THEN
           laneSel := 0; TurnCmd := 0.0; OutStep := 105;
         ELSIF NOT LaneBFull THEN
           laneSel := 1; TurnCmd := 0.0; OutStep := 105;
         END_IF;
    105: IF TurnDone THEN outRun := TRUE; OutStep := 110; END_IF;
    110: IF TurnEye THEN
           outRun := FALSE;
           IF laneSel = 1 THEN
             OutStep := 115;
           ELSE
             TurnCmd := 0.0;
             PalletFeed := TRUE;
             OutStep := 120;
           END_IF;
         END_IF;
    115: IF TurnSettle.Q THEN
           TurnCmd := -90.0;
           PalletFeed := TRUE;
           OutStep := 120;
         END_IF;
    120: IF TurnDone THEN laneRun := TRUE; OutStep := 130; END_IF;
    130: IF ((laneSel = 0) AND LaneAFull) OR ((laneSel = 1) AND LaneBFull) THEN
           laneRun := FALSE;
           TurnCmd := 0.0;
           OutStep := 140;
         END_IF;
    140: IF TurnDone THEN
           laneSel := 1 - laneSel;
           OutStep := 0;
         END_IF;
  END_CASE;
  IF PalletFeed AND FeedPulse.Q THEN
    PalletFeed := FALSE;
    palletFull := FALSE;
  END_IF;
END_IF;

IF Zone = 0 THEN
  IF Truck1.Want THEN Zone := 1; ELSIF Truck2.Want THEN Zone := 2; END_IF;
ELSIF (Zone = 1) AND NOT Truck1.Want THEN Zone := 0;
ELSIF (Zone = 2) AND NOT Truck2.Want THEN Zone := 0;
END_IF;

Truck1(Enable := safe, Idle := Agv1Idle, Grant := (Zone = 1),
       Request := LaneAFull AND NOT (laneRun AND (laneSel = 0)),
       PickBase := 1, WayBase := 6,
       WayOut := 0, WayMid := 2, WayIn := 2,
       DropBase := 10, Slots := 3);
Agv1Cmd := Truck1.Cmd; Agv1Exec := Truck1.Exec; Agv1Fork := Truck1.Fork;
A1Step := Truck1.Step; A1Slot := Truck1.Slot; A1Done := Truck1.Done;

Truck2(Enable := safe, Idle := Agv2Idle, Grant := (Zone = 2),
       Request := LaneBFull AND NOT (laneRun AND (laneSel = 1)),
       PickBase := 1, WayBase := 6,
       WayOut := 1, WayMid := 1, WayIn := 0,
       DropBase := 8, Slots := 2);
Agv2Cmd := Truck2.Cmd; Agv2Exec := Truck2.Exec; Agv2Fork := Truck2.Fork;
A2Step := Truck2.Step; A2Slot := Truck2.Slot; A2Done := Truck2.Done;

IF safe AND NOT picking THEN
  Infeed := InfeedSpeed;
  RowForm := RunSpeed;
ELSE
  Infeed := 0.0;
  RowForm := 0.0;
END_IF;
IF safe AND shifting AND Raised.Q THEN
  ShiftSpeed := ShiftRate;
ELSE
  ShiftSpeed := 0.0;
END_IF;

SpawnRun := safe AND NOT layerDone AND NOT picking AND (rowSent < rowTarget);

IF safe AND outRun THEN PalletOut := LineSpeed; ELSE PalletOut := 0.0; END_IF;
IF safe AND (outRun OR laneRun) THEN TurnRun := LineSpeed; ELSE TurnRun := 0.0; END_IF;
IF safe AND laneRun AND (laneSel = 0) THEN LaneA := LineSpeed; ELSE LaneA := 0.0; END_IF;
IF safe AND laneRun AND (laneSel = 1) THEN LaneB := LineSpeed; ELSE LaneB := 0.0; END_IF;

Turn := safe AND thisRowTurned;
Shift := shifting AND safe;

RunLamp := safe AND NOT palletFull;
Tower := 0;
IF RunLamp THEN Tower := Tower + 1; END_IF;
IF palletFull THEN Tower := Tower + 2; END_IF;
IF (NOT running) OR (NOT Guard) THEN Tower := Tower + 4; END_IF;
